INSERT INTO `dynamic_pages` (`id`, `page_slug`, `title_en`, `title_de`, `title_hu`, `sub_title_en`, `sub_title_de`, `sub_title_hu`, `description_en`, `description_de`, `description_hu`, `image`, `status`, `created_at`, `updated_at`) VALUES
(2, 'privacy-policy', 'Privacy Policy', 'Privacy Policy', 'Privacy Policy', '<p>Protecting your privacy: Our Commitment to you</p>', '<p>Protecting your privacy: Our Commitment to youProtecting your privacy: Our Commitment to you</p>', '<p>Protecting your privacy: Our Commitment to you</p>', '<p>Privacy Policy<br />\r\nLast updated: June 10, 2024<br />\r\nThis Privacy Policy describes Our policies and procedures on the collection, use and disclosure of Your information when You use the Service and tells You about Your privacy rights and how the law protects You.<br />\r\nWe use Your Personal data to provide and improve the Service. By using the Service, You agree to the collection and use of information in accordance with this Privacy Policy.<br />\r\n<br />\r\nInterpretation and Definitions<br />\r\n<br />\r\nInterpretation<br />\r\nThe words of which the initial letter is capitalized have meanings defined under the following conditions. The following definitions shall have the same meaning regardless of whether they appear in singular or in plural.<br />\r\n<br />\r\nDefinitions<br />\r\nFor the purposes of this Privacy Policy:<br />\r\n<br />\r\nAccount means a unique account created for You to access our Service or parts of our Service.<br />\r\n<br />\r\nAffiliate means an entity that controls, is controlled by or is under common control with a party, where &quot;control&quot; means ownership of 50% or more of the shares, equity interest or other securities entitled to vote for election of directors or other managing authority.<br />\r\n<br />\r\nApplication refers to TicketVilla, the software program provided by the Company.<br />\r\nCompany (referred to as either &quot;the Company&quot;, &quot;We&quot;, &quot;Us&quot; or &quot;Our&quot; in this Agreement) refers to TICKETVILLA Ltd, Dryadon, 1, Floor 1, 6041, Larnaca, Cyprus.<br />\r\nFor the purpose of the GDPR, the Company is the Data Controller.<br />\r\n<br />\r\nCookies are small files that are placed on Your computer, mobile device or any other device by a website, containing the details of Your browsing history on that website among its many uses.<br />\r\n<br />\r\nCountry refers to: Cyprus<br />\r\n<br />\r\nData Controller, for the purposes of the GDPR (General Data Protection Regulation), refers to the Company as the legal person which alone or jointly with others determines the purposes and means of the processing of Personal Data.<br />\r\n<br />\r\nDevice means any device that can access the Service such as a computer, a cellphone or a digital tablet.<br />\r\n<br />\r\nFacebook Fan Page is a public profile named Ticket Villa specifically created by the Company on the Facebook social network, accessible from https://www.facebook.com/profile.php?id=61560505499886<br />\r\n<br />\r\nGDPR refers to EU General Data Protection Regulation.<br />\r\n<br />\r\nPersonal Data is any information that relates to an identified or identifiable individual.<br />\r\nFor the purposes of GDPR, Personal Data means any information relating to You such as a name, an identification number, location data, online identifier or to one or more factors specific to the physical, physiological, genetic, mental, economic, cultural or social identity.<br />\r\n<br />\r\nService refers to the Application or the Website or both.<br />\r\n<br />\r\nService Provider means any natural or legal person who processes the data on behalf of the Company. It refers to third-party companies or individuals employed by the Company to facilitate the Service, to provide the Service on behalf of the Company, to perform services related to the Service or to assist the Company in analyzing how the Service is used. For the purpose of the GDPR, Service Providers are considered Data Processors.<br />\r\n<br />\r\nThird-party Social Media Service refers to any website or any social network website through which a User can log in or create an account to use the Service.<br />\r\nUsage Data refers to data collected automatically, either generated by the use of the Service or from the Service infrastructure itself (for example, the duration of a page visit).<br />\r\n<br />\r\nWebsite refers to TicketVilla, accessible from https://ticketvilla.eu<br />\r\n<br />\r\nYou means the individual accessing or using the Service, or the company, or other legal entity on behalf of which such individual is accessing or using the Service, as applicable.<br />\r\nUnder GDPR, You can be referred to as the Data Subject or as the User as you are the individual using the Service.<br />\r\n<br />\r\nCollecting and Using Your Personal Data<br />\r\n<br />\r\nTypes of Data Collected<br />\r\n<br />\r\nPersonal Data<br />\r\nWhile using Our Service, We may ask You to provide Us with certain personally identifiable information that can be used to contact or identify You. Personally identifiable information may include, but is not limited to:<br />\r\nEmail address<br />\r\nFirst name and last name<br />\r\nPhone number<br />\r\nAddress, State, Province, ZIP/Postal code, City<br />\r\nBank account information in order to pay for products and/or services within the Service<br />\r\nUsage Data<br />\r\n<br />\r\nWhen You pay for a product and/or a service via bank transfer, We may ask You to provide information to facilitate this transaction and to verify Your identity. Such information may include, without limitation:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Date of birth<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Passport or National ID card<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Bank card statement<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Other information linking You to an address<br />\r\n<br />\r\nUsage Data<br />\r\nUsage Data is collected automatically when using the Service.<br />\r\nUsage Data may include information such as Your Device&#39;s Internet Protocol address (e.g. IP address), browser type, browser version, the pages of our Service that You visit, the time and date of Your visit, the time spent on those pages, unique device identifiers and other diagnostic data.<br />\r\nWhen You access the Service by or through a mobile device, We may collect certain information automatically, including, but not limited to, the type of mobile device You use, Your mobile device unique ID, the IP address of Your mobile device, Your mobile operating system, the type of mobile Internet browser You use, unique device identifiers and other diagnostic data.<br />\r\nWe may also collect information that Your browser sends whenever You visit our Service or when You access the Service by or through a mobile device.<br />\r\n<br />\r\nInformation from Third-Party Social Media Services<br />\r\nThe Company allows You to create an account and log in to use the Service through the following Third-party Social Media Services:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Google<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Facebook<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Instagram<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Twitter<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; LinkedIn<br />\r\nIf You decide to register through or otherwise grant us access to a Third-Party Social Media Service, We may collect Personal data that is already associated with Your Third-Party Social Media Service&#39;s account, such as Your name, Your email address, Your activities or Your contact list associated with that account.<br />\r\nYou may also have the option of sharing additional information with the Company through Your Third-Party Social Media Service&#39;s account. If You choose to provide such information and Personal Data, during registration or otherwise, You are giving the Company permission to use, share, and store it in a manner consistent with this Privacy Policy.<br />\r\n<br />\r\nInformation Collected while Using the Application<br />\r\nWhile using Our Application, in order to provide features of Our Application, We may collect, with Your prior permission:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Information regarding your location<br />\r\nWe use this information to provide features of Our Service, to improve and customize Our Service. The information may be uploaded to the Company&#39;s servers and/or a Service Provider&#39;s server or it may be simply stored on Your device.<br />\r\nYou can enable or disable access to this information at any time, through Your Device settings.<br />\r\n<br />\r\nTracking Technologies and Cookies<br />\r\nWe use Cookies and similar tracking technologies to track the activity on Our Service and store certain information. Tracking technologies used are beacons, tags, and scripts to collect and track information and to improve and analyze Our Service. The techno.<br />\r\n<br />\r\n. Cookies or Browser Cookies. A cookie is a small file placed on Your Device. You can instruct Your browser to refuse all Cookies or to indicate when a Cookie is being sent. However, if You do not accept Cookies, You may not be able to use some parts of our Service. Unless you have adjusted Your browser setting so that it<br />\r\nwill refuse Cookies, our Service may use Cookies.<br />\r\n<br />\r\n. Web Beacons. Certain sections of our Service and our emails may contain small electronic files known as web beacons (also referred to as clear gifs, pixel tags, and single-pixel gifs) that permit the Company, for example, to count users who have visited those pages or opened an email and for other related website statistics (for example, recording the popularity of a certain section and verifying system and server integrity).<br />\r\n<br />\r\nCookies can be &quot;Persistent&quot; or &quot;Session&quot; Cookies. Persistent Cookies remain on Your personal computer or mobile device when You go offline, while Session Cookies are deleted as soon as You close Your web browser. You can learn more about cookies on TermsFeed website article.<br />\r\nWe use both Session and Persistent Cookies for the purposes set out below:<br />\r\n<br />\r\nNecessary / Essential Cookies<br />\r\nType: Session Cookies<br />\r\nAdministered by: Us<br />\r\nPurpose: These Cookies are essential to provide You with services available through the Website and to enable You to use some of its features. They help to authenticate users and prevent fraudulent use of user accounts. Without these Cookies, the services that You have asked for cannot be provided, and We only use these Cookies to provide You with those services.<br />\r\n<br />\r\nCookies Policy / Notice Acceptance Cookies<br />\r\nType: Persistent Cookies<br />\r\nAdministered by: Us<br />\r\nPurpose: These Cookies identify if users have accepted the use of cookies on the Website.<br />\r\n<br />\r\nFunctionality Cookies<br />\r\nType: Persistent Cookies<br />\r\nAdministered by: Us<br />\r\nPurpose: These Cookies allow us to remember choices You make when You use the Website, such as remembering your login details or language preference. The purpose of these Cookies is to provide You with a more personal experience and to avoid You having to re-enter your preferences every time You use the Website.<br />\r\n<br />\r\nTracking and Performance Cookies<br />\r\nType: Persistent Cookies<br />\r\nAdministered by: Third-Parties<br />\r\nPurpose: These Cookies are used to track information about traffic to the Website and how users use the Website. The information gathered via these Cookies may directly or indirectly identify you as an individual visitor. This is because the information collected is typically linked to a pseudonymous identifier associated with the device you use to access the Website. We may also use these Cookies to test new pages, features or new functionality of the Website to see how our users react to them.<br />\r\nFor more information about the cookies we use and your choices regarding cookies, please visit our Cookies Policy or the Cookies section of our Privacy Policy.<br />\r\n<br />\r\nUse of Your Personal Data<br />\r\n<br />\r\nThe Company may use Personal Data for the fallowing<br />\r\n<br />\r\n. To provide and maintain our Service, including to monitor the usage of our Service.<br />\r\n<br />\r\n. To manage Your Account: to manage Your registration as a user of the Service. The Personal Data You provide can give You access to different functionalities of the Service that are available to You as a registered use<br />\r\n<br />\r\n. For the performance of a contract: the development, compliance and undertaking of the purchase contract for the products, items or services You have purchased or of any other contract with Us through the Service.<br />\r\n<br />\r\n. To contact You: To contact You by email, telephone calls, SMS, or other equivalent forms of electronic communication, such as a mobile application&#39;s push notifications regarding updates or informative communications related to the functionalities, products or contracted services, including the security updates, when necessary or reasonable for their implementation.<br />\r\n<br />\r\n. To provide You with news, special offers and general information about other goods, services and events which we offer that are similar to those that you have already purchased or enquired about unless You have opted not to receive such information.<br />\r\n<br />\r\n. To manage Your requests: To attend and manage Your requests to Us.<br />\r\n<br />\r\n. To deliver targeted advertising to You: We may use Your information to develop and display content and advertising (and work with third-party vendors who do so) tailored to Your interests and/or location and to measure its effectiveness.<br />\r\n<br />\r\n. For business transfers: We may use Your information to evaluate or conduct a merger, divestiture, restructuring, reorganization, dissolution, or other sale or transfer of some or all of Our assets, whether as a going concern or as part of bankruptcy, liquidation, or similar proceeding, in which Personal Data held by Us about our Service users is among the assets transferred.<br />\r\n<br />\r\n. For other purposes: We may use Your information for other purposes, such as data analysis, identifying usage trends, determining the effectiveness of our promotional campaigns and to evaluate and improve our Service, products, services, marketing and your experience.<br />\r\nWe may share Your personal information in the following situations:<br />\r\n<br />\r\n. With Service Providers: We may share Your personal information with Service Providers to monitor and analyze the use of our Service, to advertise on third party websites to You after You visited our Service, for payment processing, to contact You.<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<br />\r\n. For business transfers: We may share or transfer Your personal information in connection with, or during negotiations of, any merger, sale of Company assets, financing, or acquisition of all or a portion of Our business to another company.<br />\r\n<br />\r\n. With Affiliates: We may share Your information with Our affiliates, in which case we will require those affiliates to honor this Privacy Policy. Affiliates include Our parent company and any other subsidiaries, joint venture partners or other companies that We control or that are under common control with Us.<br />\r\n<br />\r\n. With business partners: We may share Your information with Our business partners to offer You certain products, services or promotions.<br />\r\n<br />\r\n. With other users: when You share personal information or otherwise interact in the public areas with other users, such information may be viewed by all users and may be publicly distributed outside. If You interact with other users or register through a Third-Party Social Media Service, Your contacts on the Third-Party Social Media Service may see Your name, profile, pictures and description of Your activity. Similarly, other users will be able to view descriptions of Your activity, communicate with You and view Your profile.<br />\r\n<br />\r\n. With Your consent: We may disclose Your personal information for any other purpose with Your consent.<br />\r\n<br />\r\n<br />\r\nRetention of Your Personal Data<br />\r\nThe Company will retain Your Personal Data only for as long as is necessary for the purposes set out in this Privacy Policy. We will retain and use Your Personal Data to the extent necessary to comply with our legal obligations (for example, if we are required to retain your data to comply with applicable laws), resolve disputes, and enforce our legal agreements and policies.<br />\r\nThe Company will also retain Usage Data for internal analysis purposes. Usage Data is generally retained for a shorter period of time, except when this data is used to strengthen the security or to improve the functionality of Our Service, or We are legally obligated to retain this data for longer time periods.<br />\r\n<br />\r\nTransfer of Your Personal Data<br />\r\nYour information, including Personal Data, is processed at the Company&#39;s operating offices and in any other places where the parties involved in the processing are located. It means that this information may be transferred to &mdash; and maintained on &mdash; computers located outside of Your state, province, country or other governmental jurisdiction where the data protection laws may differ than those from Your jurisdiction.<br />\r\nYour consent to this Privacy Policy followed by Your submission of such information represents Your agreement to that transfer.<br />\r\nThe Company will take all steps reasonably necessary to ensure that Your data is treated securely and in accordance with this Privacy Policy and no transfer of Your Personal Data will take place to an organization or a country unless there are adequate controls in place including the security of Your data and other personal information.<br />\r\n<br />\r\nDelete Your Personal Data<br />\r\nYou have the right to delete or request that We assist in deleting the Personal Data that We have collected about You.<br />\r\nOur Service may give You the ability to delete certain information about You from within the Service.<br />\r\nYou may update, amend, or delete Your information at any time by signing in to Your Account, if you have one, and visiting the account settings section that allows you to manage Your personal information. You may also contact Us to request access to, correct, or delete any personal information that You have provided to Us.<br />\r\nPlease note, however, that We may need to retain certain information when we have a legal obligation or lawful basis to do so.<br />\r\n<br />\r\nDisclosure of Your Personal Data<br />\r\n<br />\r\nBusiness Transactions<br />\r\nIf the Company is involved in a merger, acquisition or asset sale, Your Personal Data may be transferred. We will provide notice before Your Personal Data is transferred and becomes subject to a different Privacy Policy.<br />\r\nLaw enforcement<br />\r\nUnder certain circumstances, the Company may be required to disclose Your Personal Data if required to do so by law or in response to valid requests by public authorities (e.g. a court or a government agency).<br />\r\nOther legal requirements<br />\r\nThe Company may disclose Your Personal Data in the good faith belief that such action is necessary to:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Comply with a legal obligation<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Protect and defend the rights or property of the Company<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Prevent or investigate possible wrongdoing in connection with the Service<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Protect the personal safety of Users of the Service or the public<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Protect against legal liability<br />\r\nSecurity of Your Personal Data<br />\r\nThe security of Your Personal Data is important to Us, but remember that no method of transmission over the Internet, or method of electronic storage is 100% secure. While We strive to use commercially acceptable means to protect Your Personal Data, We cannot guarantee its absolute security.<br />\r\nDetailed Information on the Processing of Your Personal Data<br />\r\nThe Service Providers We use may have access to Your Personal Data. These third-party vendors collect, store, use, process and transfer information about Your activity on Our Service in accordance with their Privacy Policies.<br />\r\nAnalytics<br />\r\nWe may use third-party Service providers to monitor and analyze the use of our Service.<br />\r\nGoogle Analytics<br />\r\nGoogle Analytics is a web analytics service offered by Google that tracks and reports website traffic. Google uses the data collected to track and monitor the use of our Service. This data is shared with other Google services. Google may use the collected data to contextualize and personalize the ads of its own advertising network.<br />\r\nYou can opt-out of having made your activity on the Service available to Google Analytics by installing the Google Analytics opt-out browser add-on. The add-on prevents the Google Analytics JavaScript (ga.js, analytics.js and dc.js) from sharing information with Google Analytics about visits activity.<br />\r\nYou may opt-out of certain Google Analytics features through your mobile device settings, such as your device advertising settings or by following the instructions provided by Google in their Privacy Policy: https://policies.google.com/privacy<br />\r\nFor more information on the privacy practices of Google, please visit the Google Privacy &amp; Terms web page: https://policies.google.com/privacy<br />\r\nFirebase<br />\r\nFirebase is an analytics service provided by Google Inc.<br />\r\nYou may opt-out of certain Firebase features through your mobile device settings, such as your device advertising settings or by following the instructions provided by Google in their Privacy Policy: https://policies.google.com/privacy<br />\r\nWe also encourage you to review the Google&#39;s policy for safeguarding your data: https://support.google.com/analytics/answer/6004245<br />\r\nFor more information on what type of information Firebase collects, please visit the How Google uses data when you use our partners&#39; sites or apps webpage: https://policies.google.com/technologies/partner-sites<br />\r\nMatomo<br />\r\nMatomo is a web analytics service. You can visit their Privacy Policy page here: https://matomo.org/privacy-policy<br />\r\nClicky<br />\r\nClicky is a web analytics service. Read the Privacy Policy for Clicky here: https://clicky.com/terms<br />\r\nFlurry Analytics<br />\r\nFlurry Analytics service is provided by Yahoo! Inc.<br />\r\nYou can opt-out from Flurry Analytics service to prevent Flurry Analytics from using and sharing your information by visiting the Flurry&#39;s Opt-out page: https://developer.yahoo.com/flurry/end-user-opt-out/<br />\r\nFor more information on the privacy practices and policies of Yahoo!, please visit their Privacy Policy page: https://policies.yahoo.com/xa/en/yahoo/privacy/index.htm<br />\r\nUnity Analytics<br />\r\nUnity Analytics is provided by Unity Technologies.<br />\r\nUnity Analytics collects, stores, uses, processes, and transfers personal information to provide, operate, and improve Unity Technologies services, including personalized advertising services. For more information on what type of information Unity Technologies collects, please visit their Privacy Policy page: https://unity3d.com/legal/privacy-policy.<br />\r\nYou can prevent Unity Analytics from using your information by opting-out. To opt-out of Unity Analytics, please visit this page: https://unity3d.com/legal/privacy-policy<br />\r\nYou may opt-out of all personalized advertising by enabling privacy features on Your mobile device such as Limit Ad Tracking (iOS) and Opt Out of Ads Personalization (Android). See Your mobile device Help system for more information.<br />\r\nHotjar<br />\r\nTheir Privacy Policy can be viewed at https://www.hotjar.com/legal/policies/privacy/<br />\r\nMeta Pixel<br />\r\nTheir Privacy Policy can be viewed at https://sites.google.com/view/metapixel-privacypolicy/home<br />\r\nFacebook Pixel<br />\r\nTheir Privacy Policy can be viewed at https://www.facebook.com/privacy/policy/<br />\r\nFacebook Conversions<br />\r\nTheir Privacy Policy can be viewed at https://www.facebook.com/privacy/policy/<br />\r\nEmail Marketing<br />\r\nWe may use Your Personal Data to contact You with newsletters, marketing or promotional materials and other information that may be of interest to You. You may opt-out of receiving any, or all, of these communications from Us by following the unsubscribe link or instructions provided in any email We send or by contacting Us.<br />\r\nWe may use Email Marketing Service Providers to manage and send emails to You.<br />\r\nMailchimp<br />\r\nMailchimp is an email marketing sending service provided by The Rocket Science Group LLC.<br />\r\nFor more information on the privacy practices of Mailchimp, please visit their Privacy policy: https://mailchimp.com/legal/privacy/<br />\r\nIntercom<br />\r\nTheir Privacy Policy can be viewed at https://www.intercom.com/legal/privacy<br />\r\nZendesk<br />\r\nTheir Privacy Policy can be viewed at https://www.zendesk.com/company/agreements-and-terms/privacy-notice/#<br />\r\nPayments<br />\r\nWe may provide paid products and/or services within the Service. In that case, we may use third-party services for payment processing (e.g. payment processors).<br />\r\nWe will not store or collect Your payment card details. That information is provided directly to Our third-party payment processors whose use of Your personal information is governed by their Privacy Policy. These payment processors adhere to the standards set by PCI-DSS as managed by the PCI Security Standards Council, which is a joint effort of brands like Visa, Mastercard, American Express and Discover. PCI-DSS requirements help ensure the secure handling of payment information.<br />\r\nApple Store In-App Payments<br />\r\nTheir Privacy Policy can be viewed at https://www.apple.com/legal/privacy/en-ww/<br />\r\nGoogle Play In-App Payments<br />\r\nTheir Privacy Policy can be viewed at https://www.google.com/policies/privacy/<br />\r\nStripe<br />\r\nTheir Privacy Policy can be viewed at https://stripe.com/us/privacy<br />\r\nShopify<br />\r\nTheir Privacy Policy can be viewed at https://www.shopify.com/legal/privacy<br />\r\nPayPal<br />\r\nTheir Privacy Policy can be viewed at https://www.paypal.com/webapps/mpp/ua/privacy-full<br />\r\nAlipay<br />\r\nTheir Privacy Policy can be viewed at https://render.alipay.com/p/f/agreementpages/alipayglobalprivacypolicy.html<br />\r\nAmazon Pay<br />\r\nTheir Privacy Policy can be viewed at https://www.amazon.in/gp/help/customer/display.html?nodeId=202136010<br />\r\nWhen You use Our Service to pay a product and/or service via bank transfer, We may ask You to provide information to facilitate this transaction and to verify Your identity.<br />\r\nBehavioral Remarketing<br />\r\nThe Company uses remarketing services to advertise to You after You accessed or visited our Service. We and Our third-party vendors use cookies and non-cookie technologies to help Us recognize Your Device and understand how You use our Service so that We can improve our Service to reflect Your interests and serve You advertisements that are likely to be of more interest to You.<br />\r\nThese third-party vendors collect, store, use, process and transfer information about Your activity on Our Service in accordance with their Privacy Policies and to enable Us to:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Measure and analyze traffic and browsing activity on Our Service<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Show advertisements for our products and/or services to You on third-party websites or apps<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Measure and analyze the performance of Our advertising campaigns<br />\r\nSome of these third-party vendors may use non-cookie technologies that may not be impacted by browser settings that block cookies. Your browser may not permit You to block such technologies. You can use the following third-party tools to decline the collection and use of information for the purpose of serving You interest-based advertising:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; The NAI&#39;s opt-out platform: http://www.networkadvertising.org/choices/<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; The EDAA&#39;s opt-out platform http://www.youronlinechoices.com/<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; The DAA&#39;s opt-out platform: http://optout.aboutads.info/?c=2&amp;lang=EN<br />\r\nYou may opt-out of all personalized advertising by enabling privacy features on Your mobile device such as Limit Ad Tracking (iOS) and Opt Out of Ads Personalization (Android). See Your mobile device Help system for more information.<br />\r\nWe may share information, such as hashed email addresses (if available) or other online identifiers collected on Our Service with these third-party vendors. This allows Our third-party vendors to recognize and deliver You ads across devices and browsers. To read more about the technologies used by these third-party vendors and their cross-device capabilities please refer to the Privacy Policy of each vendor listed below.<br />\r\nThe third-party vendors We use are:<br />\r\nGoogle Ads (AdWords)<br />\r\nGoogle Ads (AdWords) remarketing service is provided by Google Inc.<br />\r\nYou can opt-out of Google Analytics for Display Advertising and customize the Google Display Network ads by visiting the Google Ads Settings page: http://www.google.com/settings/ads<br />\r\nGoogle also recommends installing the Google Analytics Opt-out Browser Add-on - https://tools.google.com/dlpage/gaoptout - for your web browser. Google Analytics Opt-out Browser Add-on provides visitors with the ability to prevent their data from being collected and used by Google Analytics.<br />\r\nFor more information on the privacy practices of Google, please visit the Google Privacy &amp; Terms web page: https://policies.google.com/privacy<br />\r\nTwitter<br />\r\nTwitter remarketing service is provided by Twitter Inc.<br />\r\nYou can opt-out from Twitter&#39;s interest-based ads by following their instructions: https://support.twitter.com/articles/20170405<br />\r\nYou can learn more about the privacy practices and policies of Twitter by visiting their Privacy Policy page: https://twitter.com/privacy<br />\r\nFacebook<br />\r\nFacebook remarketing service is provided by Facebook Inc.<br />\r\nYou can learn more about interest-based advertising from Facebook by visiting this page: https://www.facebook.com/help/516147308587266<br />\r\nTo opt-out from Facebook&#39;s interest-based ads, follow these instructions from Facebook: https://www.facebook.com/help/568137493302217<br />\r\nFacebook adheres to the Self-Regulatory Principles for Online Behavioural Advertising established by the Digital Advertising Alliance. You can also opt-out from Facebook and other participating companies through the Digital Advertising Alliance in the USA http://www.aboutads.info/choices/, the Digital Advertising Alliance of Canada in Canada http://youradchoices.ca/ or the European Interactive Digital Advertising Alliance in Europe http://www.youronlinechoices.eu/, or opt-out using your mobile device settings.<br />\r\nFor more information on the privacy practices of Facebook, please visit Facebook&#39;s Data Policy: https://www.facebook.com/privacy/explanation<br />\r\nUsage, Performance and Miscellaneous<br />\r\nWe may use third-party Service Providers to maintain and improve our Service.<br />\r\nInvisible reCAPTCHA<br />\r\nWe use an invisible captcha service named reCAPTCHA. reCAPTCHA is operated by Google.<br />\r\nThe reCAPTCHA service may collect information from You and from Your Device for security purposes.<br />\r\nThe information gathered by reCAPTCHA is held in accordance with the Privacy Policy of Google: https://www.google.com/intl/en/policies/privacy/<br />\r\nGDPR Privacy<br />\r\nLegal Basis for Processing Personal Data under GDPR<br />\r\nWe may process Personal Data under the following conditions:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Consent: You have given Your consent for processing Personal Data for one or more specific purposes.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Performance of a contract: Provision of Personal Data is necessary for the performance of an agreement with You and/or for any pre-contractual obligations thereof.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Legal obligations: Processing Personal Data is necessary for compliance with a legal obligation to which the Company is subject.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Vital interests: Processing Personal Data is necessary in order to protect Your vital interests or of another natural person.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Public interests: Processing Personal Data is related to a task that is carried out in the public interest or in the exercise of official authority vested in the Company.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Legitimate interests: Processing Personal Data is necessary for the purposes of the legitimate interests pursued by the Company.<br />\r\nIn any case, the Company will gladly help to clarify the specific legal basis that applies to the processing, and in particular whether the provision of Personal Data is a statutory or contractual requirement, or a requirement necessary to enter into a contract.<br />\r\nYour Rights under the GDPR<br />\r\nThe Company undertakes to respect the confidentiality of Your Personal Data and to guarantee You can exercise Your rights.<br />\r\nYou have the right under this Privacy Policy, and by law if You are within the EU, to:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Request access to Your Personal Data. The right to access, update or delete the information We have on You. Whenever made possible, you can access, update or request deletion of Your Personal Data directly within Your account settings section. If you are unable to perform these actions yourself, please contact Us to assist You. This also enables You to receive a copy of the Personal Data We hold about You.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Request correction of the Personal Data that We hold about You. You have the right to have any incomplete or inaccurate information We hold about You corrected.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Object to processing of Your Personal Data. This right exists where We are relying on a legitimate interest as the legal basis for Our processing and there is something about Your particular situation, which makes You want to object to our processing of Your Personal Data on this ground. You also have the right to object where We are processing Your Personal Data for direct marketing purposes.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Request erasure of Your Personal Data. You have the right to ask Us to delete or remove Personal Data when there is no good reason for Us to continue processing it.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Request the transfer of Your Personal Data. We will provide to You, or to a third-party You have chosen, Your Personal Data in a structured, commonly used, machine-readable format. Please note that this right only applies to automated information which You initially provided consent for Us to use or where We used the information to perform a contract with You.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Withdraw Your consent. You have the right to withdraw Your consent on using your Personal Data. If You withdraw Your consent, We may not be able to provide You with access to certain specific functionalities of the Service.<br />\r\nExercising of Your GDPR Data Protection Rights<br />\r\nYou may exercise Your rights of access, rectification, cancellation and opposition by contacting Us. Please note that we may ask You to verify Your identity before responding to such requests. If You make a request, We will try our best to respond to You as soon as possible.<br />\r\nYou have the right to complain to a Data Protection Authority about Our collection and use of Your Personal Data. For more information, if You are in the European Economic Area (EEA), please contact Your local data protection authority in the EEA.<br />\r\nFacebook Fan Page<br />\r\nData Controller for the Facebook Fan Page<br />\r\nThe Company is the Data Controller of Your Personal Data collected while using the Service. As operator of the Facebook Fan Page https://www.facebook.com/profile.php?id=61560505499886, the Company and the operator of the social network Facebook are Joint Controllers.<br />\r\nThe Company has entered into agreements with Facebook that define the terms for use of the Facebook Fan Page, among other things. These terms are mostly based on the Facebook Terms of Service: https://www.facebook.com/terms.php<br />\r\nVisit the Facebook Privacy Policy https://www.facebook.com/policy.php for more information about how Facebook manages Personal data or contact Facebook online, or by mail: Facebook, Inc. ATTN, Privacy Operations, 1601 Willow Road, Menlo Park, CA 94025, United States.<br />\r\nFacebook Insights<br />\r\nWe use the Facebook Insights function in connection with the operation of the Facebook Fan Page and on the basis of the GDPR, in order to obtain anonymized statistical data about Our users.<br />\r\nFor this purpose, Facebook places a Cookie on the device of the user visiting Our Facebook Fan Page. Each Cookie contains a unique identifier code and remains active for a period of two years, except when it is deleted before the end of this period.<br />\r\nFacebook receives, records and processes the information stored in the Cookie, especially when the user visits the Facebook services, services that are provided by other members of the Facebook Fan Page and services by other companies that use Facebook services.<br />\r\nFor more information on the privacy practices of Facebook, please visit Facebook Privacy Policy here: https://www.facebook.com/privacy/explanation<br />\r\nChildren&#39;s Privacy<br />\r\nOur Service does not address anyone under the age of 13. We do not knowingly collect personally identifiable information from anyone under the age of 13. If You are a parent or guardian and You are aware that Your child has provided Us with Personal Data, please contact Us. If We become aware that We have collected Personal Data from anyone under the age of 13 without verification of parental consent, We take steps to remove that information from Our servers.<br />\r\nIf We need to rely on consent as a legal basis for processing Your information and Your country requires consent from a parent, We may require Your parent&#39;s consent before We collect and use that information.<br />\r\nLinks to Other Websites<br />\r\nOur Service may contain links to other websites that are not operated by Us. If You click on a third party link, You will be directed to that third party&#39;s site. We strongly advise You to review the Privacy Policy of every site You visit.<br />\r\nWe have no control over and assume no responsibility for the content, privacy policies or practices of any third party sites or services.<br />\r\nChanges to this Privacy Policy<br />\r\nWe may update Our Privacy Policy from time to time. We will notify You of any changes by posting the new Privacy Policy on this page.<br />\r\nWe will let You know via email and/or a prominent notice on Our Service, prior to the change becoming effective and update the &quot;Last updated&quot; date at the top of this Privacy Policy.<br />\r\nYou are advised to review this Privacy Policy periodically for any changes. Changes to this Privacy Policy are effective when they are posted on this page.<br />\r\nContact Us<br />\r\nIf you have any questions about this Privacy Policy, You can contact us:<br />\r\nBy email: ebook@ticketvilla.eu<br />\r\nBy visiting this page on our website: https://ticketvilla.eu<br />\r\nBy phone number: +13474740085<br />\r\nBy mail: Dryadon, 1, Floor 1, 6041, Larnaca, Cyprus</p>', '<p>Privacy Policy<br />\r\nLast updated: June 10, 2024<br />\r\nThis Privacy Policy describes Our policies and procedures on the collection, use and disclosure of Your information when You use the Service and tells You about Your privacy rights and how the law protects You.<br />\r\nWe use Your Personal data to provide and improve the Service. By using the Service, You agree to the collection and use of information in accordance with this Privacy Policy.<br />\r\n<br />\r\nInterpretation and Definitions<br />\r\n<br />\r\nInterpretation<br />\r\nThe words of which the initial letter is capitalized have meanings defined under the following conditions. The following definitions shall have the same meaning regardless of whether they appear in singular or in plural.<br />\r\n<br />\r\nDefinitions<br />\r\nFor the purposes of this Privacy Policy:<br />\r\n<br />\r\nAccount means a unique account created for You to access our Service or parts of our Service.<br />\r\n<br />\r\nAffiliate means an entity that controls, is controlled by or is under common control with a party, where &quot;control&quot; means ownership of 50% or more of the shares, equity interest or other securities entitled to vote for election of directors or other managing authority.<br />\r\n<br />\r\nApplication refers to TicketVilla, the software program provided by the Company.<br />\r\nCompany (referred to as either &quot;the Company&quot;, &quot;We&quot;, &quot;Us&quot; or &quot;Our&quot; in this Agreement) refers to TICKETVILLA Ltd, Dryadon, 1, Floor 1, 6041, Larnaca, Cyprus.<br />\r\nFor the purpose of the GDPR, the Company is the Data Controller.<br />\r\n<br />\r\nCookies are small files that are placed on Your computer, mobile device or any other device by a website, containing the details of Your browsing history on that website among its many uses.<br />\r\n<br />\r\nCountry refers to: Cyprus<br />\r\n<br />\r\nData Controller, for the purposes of the GDPR (General Data Protection Regulation), refers to the Company as the legal person which alone or jointly with others determines the purposes and means of the processing of Personal Data.<br />\r\n<br />\r\nDevice means any device that can access the Service such as a computer, a cellphone or a digital tablet.<br />\r\n<br />\r\nFacebook Fan Page is a public profile named Ticket Villa specifically created by the Company on the Facebook social network, accessible from https://www.facebook.com/profile.php?id=61560505499886<br />\r\n<br />\r\nGDPR refers to EU General Data Protection Regulation.<br />\r\n<br />\r\nPersonal Data is any information that relates to an identified or identifiable individual.<br />\r\nFor the purposes of GDPR, Personal Data means any information relating to You such as a name, an identification number, location data, online identifier or to one or more factors specific to the physical, physiological, genetic, mental, economic, cultural or social identity.<br />\r\n<br />\r\nService refers to the Application or the Website or both.<br />\r\n<br />\r\nService Provider means any natural or legal person who processes the data on behalf of the Company. It refers to third-party companies or individuals employed by the Company to facilitate the Service, to provide the Service on behalf of the Company, to perform services related to the Service or to assist the Company in analyzing how the Service is used. For the purpose of the GDPR, Service Providers are considered Data Processors.<br />\r\n<br />\r\nThird-party Social Media Service refers to any website or any social network website through which a User can log in or create an account to use the Service.<br />\r\nUsage Data refers to data collected automatically, either generated by the use of the Service or from the Service infrastructure itself (for example, the duration of a page visit).<br />\r\n<br />\r\nWebsite refers to TicketVilla, accessible from https://ticketvilla.eu<br />\r\n<br />\r\nYou means the individual accessing or using the Service, or the company, or other legal entity on behalf of which such individual is accessing or using the Service, as applicable.<br />\r\nUnder GDPR, You can be referred to as the Data Subject or as the User as you are the individual using the Service.<br />\r\n<br />\r\nCollecting and Using Your Personal Data<br />\r\n<br />\r\nTypes of Data Collected<br />\r\n<br />\r\nPersonal Data<br />\r\nWhile using Our Service, We may ask You to provide Us with certain personally identifiable information that can be used to contact or identify You. Personally identifiable information may include, but is not limited to:<br />\r\nEmail address<br />\r\nFirst name and last name<br />\r\nPhone number<br />\r\nAddress, State, Province, ZIP/Postal code, City<br />\r\nBank account information in order to pay for products and/or services within the Service<br />\r\nUsage Data<br />\r\n<br />\r\nWhen You pay for a product and/or a service via bank transfer, We may ask You to provide information to facilitate this transaction and to verify Your identity. Such information may include, without limitation:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Date of birth<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Passport or National ID card<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Bank card statement<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Other information linking You to an address<br />\r\n<br />\r\nUsage Data<br />\r\nUsage Data is collected automatically when using the Service.<br />\r\nUsage Data may include information such as Your Device&#39;s Internet Protocol address (e.g. IP address), browser type, browser version, the pages of our Service that You visit, the time and date of Your visit, the time spent on those pages, unique device identifiers and other diagnostic data.<br />\r\nWhen You access the Service by or through a mobile device, We may collect certain information automatically, including, but not limited to, the type of mobile device You use, Your mobile device unique ID, the IP address of Your mobile device, Your mobile operating system, the type of mobile Internet browser You use, unique device identifiers and other diagnostic data.<br />\r\nWe may also collect information that Your browser sends whenever You visit our Service or when You access the Service by or through a mobile device.<br />\r\n<br />\r\nInformation from Third-Party Social Media Services<br />\r\nThe Company allows You to create an account and log in to use the Service through the following Third-party Social Media Services:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Google<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Facebook<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Instagram<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Twitter<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; LinkedIn<br />\r\nIf You decide to register through or otherwise grant us access to a Third-Party Social Media Service, We may collect Personal data that is already associated with Your Third-Party Social Media Service&#39;s account, such as Your name, Your email address, Your activities or Your contact list associated with that account.<br />\r\nYou may also have the option of sharing additional information with the Company through Your Third-Party Social Media Service&#39;s account. If You choose to provide such information and Personal Data, during registration or otherwise, You are giving the Company permission to use, share, and store it in a manner consistent with this Privacy Policy.<br />\r\n<br />\r\nInformation Collected while Using the Application<br />\r\nWhile using Our Application, in order to provide features of Our Application, We may collect, with Your prior permission:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Information regarding your location<br />\r\nWe use this information to provide features of Our Service, to improve and customize Our Service. The information may be uploaded to the Company&#39;s servers and/or a Service Provider&#39;s server or it may be simply stored on Your device.<br />\r\nYou can enable or disable access to this information at any time, through Your Device settings.<br />\r\n<br />\r\nTracking Technologies and Cookies<br />\r\nWe use Cookies and similar tracking technologies to track the activity on Our Service and store certain information. Tracking technologies used are beacons, tags, and scripts to collect and track information and to improve and analyze Our Service. The techno.<br />\r\n<br />\r\n. Cookies or Browser Cookies. A cookie is a small file placed on Your Device. You can instruct Your browser to refuse all Cookies or to indicate when a Cookie is being sent. However, if You do not accept Cookies, You may not be able to use some parts of our Service. Unless you have adjusted Your browser setting so that it<br />\r\nwill refuse Cookies, our Service may use Cookies.<br />\r\n<br />\r\n. Web Beacons. Certain sections of our Service and our emails may contain small electronic files known as web beacons (also referred to as clear gifs, pixel tags, and single-pixel gifs) that permit the Company, for example, to count users who have visited those pages or opened an email and for other related website statistics (for example, recording the popularity of a certain section and verifying system and server integrity).<br />\r\n<br />\r\nCookies can be &quot;Persistent&quot; or &quot;Session&quot; Cookies. Persistent Cookies remain on Your personal computer or mobile device when You go offline, while Session Cookies are deleted as soon as You close Your web browser. You can learn more about cookies on TermsFeed website article.<br />\r\nWe use both Session and Persistent Cookies for the purposes set out below:<br />\r\n<br />\r\nNecessary / Essential Cookies<br />\r\nType: Session Cookies<br />\r\nAdministered by: Us<br />\r\nPurpose: These Cookies are essential to provide You with services available through the Website and to enable You to use some of its features. They help to authenticate users and prevent fraudulent use of user accounts. Without these Cookies, the services that You have asked for cannot be provided, and We only use these Cookies to provide You with those services.<br />\r\n<br />\r\nCookies Policy / Notice Acceptance Cookies<br />\r\nType: Persistent Cookies<br />\r\nAdministered by: Us<br />\r\nPurpose: These Cookies identify if users have accepted the use of cookies on the Website.<br />\r\n<br />\r\nFunctionality Cookies<br />\r\nType: Persistent Cookies<br />\r\nAdministered by: Us<br />\r\nPurpose: These Cookies allow us to remember choices You make when You use the Website, such as remembering your login details or language preference. The purpose of these Cookies is to provide You with a more personal experience and to avoid You having to re-enter your preferences every time You use the Website.<br />\r\n<br />\r\nTracking and Performance Cookies<br />\r\nType: Persistent Cookies<br />\r\nAdministered by: Third-Parties<br />\r\nPurpose: These Cookies are used to track information about traffic to the Website and how users use the Website. The information gathered via these Cookies may directly or indirectly identify you as an individual visitor. This is because the information collected is typically linked to a pseudonymous identifier associated with the device you use to access the Website. We may also use these Cookies to test new pages, features or new functionality of the Website to see how our users react to them.<br />\r\nFor more information about the cookies we use and your choices regarding cookies, please visit our Cookies Policy or the Cookies section of our Privacy Policy.<br />\r\n<br />\r\nUse of Your Personal Data<br />\r\n<br />\r\nThe Company may use Personal Data for the fallowing<br />\r\n<br />\r\n. To provide and maintain our Service, including to monitor the usage of our Service.<br />\r\n<br />\r\n. To manage Your Account: to manage Your registration as a user of the Service. The Personal Data You provide can give You access to different functionalities of the Service that are available to You as a registered use<br />\r\n<br />\r\n. For the performance of a contract: the development, compliance and undertaking of the purchase contract for the products, items or services You have purchased or of any other contract with Us through the Service.<br />\r\n<br />\r\n. To contact You: To contact You by email, telephone calls, SMS, or other equivalent forms of electronic communication, such as a mobile application&#39;s push notifications regarding updates or informative communications related to the functionalities, products or contracted services, including the security updates, when necessary or reasonable for their implementation.<br />\r\n<br />\r\n. To provide You with news, special offers and general information about other goods, services and events which we offer that are similar to those that you have already purchased or enquired about unless You have opted not to receive such information.<br />\r\n<br />\r\n. To manage Your requests: To attend and manage Your requests to Us.<br />\r\n<br />\r\n. To deliver targeted advertising to You: We may use Your information to develop and display content and advertising (and work with third-party vendors who do so) tailored to Your interests and/or location and to measure its effectiveness.<br />\r\n<br />\r\n. For business transfers: We may use Your information to evaluate or conduct a merger, divestiture, restructuring, reorganization, dissolution, or other sale or transfer of some or all of Our assets, whether as a going concern or as part of bankruptcy, liquidation, or similar proceeding, in which Personal Data held by Us about our Service users is among the assets transferred.<br />\r\n<br />\r\n. For other purposes: We may use Your information for other purposes, such as data analysis, identifying usage trends, determining the effectiveness of our promotional campaigns and to evaluate and improve our Service, products, services, marketing and your experience.<br />\r\nWe may share Your personal information in the following situations:<br />\r\n<br />\r\n. With Service Providers: We may share Your personal information with Service Providers to monitor and analyze the use of our Service, to advertise on third party websites to You after You visited our Service, for payment processing, to contact You.<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<br />\r\n. For business transfers: We may share or transfer Your personal information in connection with, or during negotiations of, any merger, sale of Company assets, financing, or acquisition of all or a portion of Our business to another company.<br />\r\n<br />\r\n. With Affiliates: We may share Your information with Our affiliates, in which case we will require those affiliates to honor this Privacy Policy. Affiliates include Our parent company and any other subsidiaries, joint venture partners or other companies that We control or that are under common control with Us.<br />\r\n<br />\r\n. With business partners: We may share Your information with Our business partners to offer You certain products, services or promotions.<br />\r\n<br />\r\n. With other users: when You share personal information or otherwise interact in the public areas with other users, such information may be viewed by all users and may be publicly distributed outside. If You interact with other users or register through a Third-Party Social Media Service, Your contacts on the Third-Party Social Media Service may see Your name, profile, pictures and description of Your activity. Similarly, other users will be able to view descriptions of Your activity, communicate with You and view Your profile.<br />\r\n<br />\r\n. With Your consent: We may disclose Your personal information for any other purpose with Your consent.<br />\r\n<br />\r\n<br />\r\nRetention of Your Personal Data<br />\r\nThe Company will retain Your Personal Data only for as long as is necessary for the purposes set out in this Privacy Policy. We will retain and use Your Personal Data to the extent necessary to comply with our legal obligations (for example, if we are required to retain your data to comply with applicable laws), resolve disputes, and enforce our legal agreements and policies.<br />\r\nThe Company will also retain Usage Data for internal analysis purposes. Usage Data is generally retained for a shorter period of time, except when this data is used to strengthen the security or to improve the functionality of Our Service, or We are legally obligated to retain this data for longer time periods.<br />\r\n<br />\r\nTransfer of Your Personal Data<br />\r\nYour information, including Personal Data, is processed at the Company&#39;s operating offices and in any other places where the parties involved in the processing are located. It means that this information may be transferred to &mdash; and maintained on &mdash; computers located outside of Your state, province, country or other governmental jurisdiction where the data protection laws may differ than those from Your jurisdiction.<br />\r\nYour consent to this Privacy Policy followed by Your submission of such information represents Your agreement to that transfer.<br />\r\nThe Company will take all steps reasonably necessary to ensure that Your data is treated securely and in accordance with this Privacy Policy and no transfer of Your Personal Data will take place to an organization or a country unless there are adequate controls in place including the security of Your data and other personal information.<br />\r\n<br />\r\nDelete Your Personal Data<br />\r\nYou have the right to delete or request that We assist in deleting the Personal Data that We have collected about You.<br />\r\nOur Service may give You the ability to delete certain information about You from within the Service.<br />\r\nYou may update, amend, or delete Your information at any time by signing in to Your Account, if you have one, and visiting the account settings section that allows you to manage Your personal information. You may also contact Us to request access to, correct, or delete any personal information that You have provided to Us.<br />\r\nPlease note, however, that We may need to retain certain information when we have a legal obligation or lawful basis to do so.<br />\r\n<br />\r\nDisclosure of Your Personal Data<br />\r\n<br />\r\nBusiness Transactions<br />\r\nIf the Company is involved in a merger, acquisition or asset sale, Your Personal Data may be transferred. We will provide notice before Your Personal Data is transferred and becomes subject to a different Privacy Policy.<br />\r\nLaw enforcement<br />\r\nUnder certain circumstances, the Company may be required to disclose Your Personal Data if required to do so by law or in response to valid requests by public authorities (e.g. a court or a government agency).<br />\r\nOther legal requirements<br />\r\nThe Company may disclose Your Personal Data in the good faith belief that such action is necessary to:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Comply with a legal obligation<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Protect and defend the rights or property of the Company<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Prevent or investigate possible wrongdoing in connection with the Service<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Protect the personal safety of Users of the Service or the public<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Protect against legal liability<br />\r\nSecurity of Your Personal Data<br />\r\nThe security of Your Personal Data is important to Us, but remember that no method of transmission over the Internet, or method of electronic storage is 100% secure. While We strive to use commercially acceptable means to protect Your Personal Data, We cannot guarantee its absolute security.<br />\r\nDetailed Information on the Processing of Your Personal Data<br />\r\nThe Service Providers We use may have access to Your Personal Data. These third-party vendors collect, store, use, process and transfer information about Your activity on Our Service in accordance with their Privacy Policies.<br />\r\nAnalytics<br />\r\nWe may use third-party Service providers to monitor and analyze the use of our Service.<br />\r\nGoogle Analytics<br />\r\nGoogle Analytics is a web analytics service offered by Google that tracks and reports website traffic. Google uses the data collected to track and monitor the use of our Service. This data is shared with other Google services. Google may use the collected data to contextualize and personalize the ads of its own advertising network.<br />\r\nYou can opt-out of having made your activity on the Service available to Google Analytics by installing the Google Analytics opt-out browser add-on. The add-on prevents the Google Analytics JavaScript (ga.js, analytics.js and dc.js) from sharing information with Google Analytics about visits activity.<br />\r\nYou may opt-out of certain Google Analytics features through your mobile device settings, such as your device advertising settings or by following the instructions provided by Google in their Privacy Policy: https://policies.google.com/privacy<br />\r\nFor more information on the privacy practices of Google, please visit the Google Privacy &amp; Terms web page: https://policies.google.com/privacy<br />\r\nFirebase<br />\r\nFirebase is an analytics service provided by Google Inc.<br />\r\nYou may opt-out of certain Firebase features through your mobile device settings, such as your device advertising settings or by following the instructions provided by Google in their Privacy Policy: https://policies.google.com/privacy<br />\r\nWe also encourage you to review the Google&#39;s policy for safeguarding your data: https://support.google.com/analytics/answer/6004245<br />\r\nFor more information on what type of information Firebase collects, please visit the How Google uses data when you use our partners&#39; sites or apps webpage: https://policies.google.com/technologies/partner-sites<br />\r\nMatomo<br />\r\nMatomo is a web analytics service. You can visit their Privacy Policy page here: https://matomo.org/privacy-policy<br />\r\nClicky<br />\r\nClicky is a web analytics service. Read the Privacy Policy for Clicky here: https://clicky.com/terms<br />\r\nFlurry Analytics<br />\r\nFlurry Analytics service is provided by Yahoo! Inc.<br />\r\nYou can opt-out from Flurry Analytics service to prevent Flurry Analytics from using and sharing your information by visiting the Flurry&#39;s Opt-out page: https://developer.yahoo.com/flurry/end-user-opt-out/<br />\r\nFor more information on the privacy practices and policies of Yahoo!, please visit their Privacy Policy page: https://policies.yahoo.com/xa/en/yahoo/privacy/index.htm<br />\r\nUnity Analytics<br />\r\nUnity Analytics is provided by Unity Technologies.<br />\r\nUnity Analytics collects, stores, uses, processes, and transfers personal information to provide, operate, and improve Unity Technologies services, including personalized advertising services. For more information on what type of information Unity Technologies collects, please visit their Privacy Policy page: https://unity3d.com/legal/privacy-policy.<br />\r\nYou can prevent Unity Analytics from using your information by opting-out. To opt-out of Unity Analytics, please visit this page: https://unity3d.com/legal/privacy-policy<br />\r\nYou may opt-out of all personalized advertising by enabling privacy features on Your mobile device such as Limit Ad Tracking (iOS) and Opt Out of Ads Personalization (Android). See Your mobile device Help system for more information.<br />\r\nHotjar<br />\r\nTheir Privacy Policy can be viewed at https://www.hotjar.com/legal/policies/privacy/<br />\r\nMeta Pixel<br />\r\nTheir Privacy Policy can be viewed at https://sites.google.com/view/metapixel-privacypolicy/home<br />\r\nFacebook Pixel<br />\r\nTheir Privacy Policy can be viewed at https://www.facebook.com/privacy/policy/<br />\r\nFacebook Conversions<br />\r\nTheir Privacy Policy can be viewed at https://www.facebook.com/privacy/policy/<br />\r\nEmail Marketing<br />\r\nWe may use Your Personal Data to contact You with newsletters, marketing or promotional materials and other information that may be of interest to You. You may opt-out of receiving any, or all, of these communications from Us by following the unsubscribe link or instructions provided in any email We send or by contacting Us.<br />\r\nWe may use Email Marketing Service Providers to manage and send emails to You.<br />\r\nMailchimp<br />\r\nMailchimp is an email marketing sending service provided by The Rocket Science Group LLC.<br />\r\nFor more information on the privacy practices of Mailchimp, please visit their Privacy policy: https://mailchimp.com/legal/privacy/<br />\r\nIntercom<br />\r\nTheir Privacy Policy can be viewed at https://www.intercom.com/legal/privacy<br />\r\nZendesk<br />\r\nTheir Privacy Policy can be viewed at https://www.zendesk.com/company/agreements-and-terms/privacy-notice/#<br />\r\nPayments<br />\r\nWe may provide paid products and/or services within the Service. In that case, we may use third-party services for payment processing (e.g. payment processors).<br />\r\nWe will not store or collect Your payment card details. That information is provided directly to Our third-party payment processors whose use of Your personal information is governed by their Privacy Policy. These payment processors adhere to the standards set by PCI-DSS as managed by the PCI Security Standards Council, which is a joint effort of brands like Visa, Mastercard, American Express and Discover. PCI-DSS requirements help ensure the secure handling of payment information.<br />\r\nApple Store In-App Payments<br />\r\nTheir Privacy Policy can be viewed at https://www.apple.com/legal/privacy/en-ww/<br />\r\nGoogle Play In-App Payments<br />\r\nTheir Privacy Policy can be viewed at https://www.google.com/policies/privacy/<br />\r\nStripe<br />\r\nTheir Privacy Policy can be viewed at https://stripe.com/us/privacy<br />\r\nShopify<br />\r\nTheir Privacy Policy can be viewed at https://www.shopify.com/legal/privacy<br />\r\nPayPal<br />\r\nTheir Privacy Policy can be viewed at https://www.paypal.com/webapps/mpp/ua/privacy-full<br />\r\nAlipay<br />\r\nTheir Privacy Policy can be viewed at https://render.alipay.com/p/f/agreementpages/alipayglobalprivacypolicy.html<br />\r\nAmazon Pay<br />\r\nTheir Privacy Policy can be viewed at https://www.amazon.in/gp/help/customer/display.html?nodeId=202136010<br />\r\nWhen You use Our Service to pay a product and/or service via bank transfer, We may ask You to provide information to facilitate this transaction and to verify Your identity.<br />\r\nBehavioral Remarketing<br />\r\nThe Company uses remarketing services to advertise to You after You accessed or visited our Service. We and Our third-party vendors use cookies and non-cookie technologies to help Us recognize Your Device and understand how You use our Service so that We can improve our Service to reflect Your interests and serve You advertisements that are likely to be of more interest to You.<br />\r\nThese third-party vendors collect, store, use, process and transfer information about Your activity on Our Service in accordance with their Privacy Policies and to enable Us to:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Measure and analyze traffic and browsing activity on Our Service<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Show advertisements for our products and/or services to You on third-party websites or apps<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Measure and analyze the performance of Our advertising campaigns<br />\r\nSome of these third-party vendors may use non-cookie technologies that may not be impacted by browser settings that block cookies. Your browser may not permit You to block such technologies. You can use the following third-party tools to decline the collection and use of information for the purpose of serving You interest-based advertising:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; The NAI&#39;s opt-out platform: http://www.networkadvertising.org/choices/<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; The EDAA&#39;s opt-out platform http://www.youronlinechoices.com/<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; The DAA&#39;s opt-out platform: http://optout.aboutads.info/?c=2&amp;lang=EN<br />\r\nYou may opt-out of all personalized advertising by enabling privacy features on Your mobile device such as Limit Ad Tracking (iOS) and Opt Out of Ads Personalization (Android). See Your mobile device Help system for more information.<br />\r\nWe may share information, such as hashed email addresses (if available) or other online identifiers collected on Our Service with these third-party vendors. This allows Our third-party vendors to recognize and deliver You ads across devices and browsers. To read more about the technologies used by these third-party vendors and their cross-device capabilities please refer to the Privacy Policy of each vendor listed below.<br />\r\nThe third-party vendors We use are:<br />\r\nGoogle Ads (AdWords)<br />\r\nGoogle Ads (AdWords) remarketing service is provided by Google Inc.<br />\r\nYou can opt-out of Google Analytics for Display Advertising and customize the Google Display Network ads by visiting the Google Ads Settings page: http://www.google.com/settings/ads<br />\r\nGoogle also recommends installing the Google Analytics Opt-out Browser Add-on - https://tools.google.com/dlpage/gaoptout - for your web browser. Google Analytics Opt-out Browser Add-on provides visitors with the ability to prevent their data from being collected and used by Google Analytics.<br />\r\nFor more information on the privacy practices of Google, please visit the Google Privacy &amp; Terms web page: https://policies.google.com/privacy<br />\r\nTwitter<br />\r\nTwitter remarketing service is provided by Twitter Inc.<br />\r\nYou can opt-out from Twitter&#39;s interest-based ads by following their instructions: https://support.twitter.com/articles/20170405<br />\r\nYou can learn more about the privacy practices and policies of Twitter by visiting their Privacy Policy page: https://twitter.com/privacy<br />\r\nFacebook<br />\r\nFacebook remarketing service is provided by Facebook Inc.<br />\r\nYou can learn more about interest-based advertising from Facebook by visiting this page: https://www.facebook.com/help/516147308587266<br />\r\nTo opt-out from Facebook&#39;s interest-based ads, follow these instructions from Facebook: https://www.facebook.com/help/568137493302217<br />\r\nFacebook adheres to the Self-Regulatory Principles for Online Behavioural Advertising established by the Digital Advertising Alliance. You can also opt-out from Facebook and other participating companies through the Digital Advertising Alliance in the USA http://www.aboutads.info/choices/, the Digital Advertising Alliance of Canada in Canada http://youradchoices.ca/ or the European Interactive Digital Advertising Alliance in Europe http://www.youronlinechoices.eu/, or opt-out using your mobile device settings.<br />\r\nFor more information on the privacy practices of Facebook, please visit Facebook&#39;s Data Policy: https://www.facebook.com/privacy/explanation<br />\r\nUsage, Performance and Miscellaneous<br />\r\nWe may use third-party Service Providers to maintain and improve our Service.<br />\r\nInvisible reCAPTCHA<br />\r\nWe use an invisible captcha service named reCAPTCHA. reCAPTCHA is operated by Google.<br />\r\nThe reCAPTCHA service may collect information from You and from Your Device for security purposes.<br />\r\nThe information gathered by reCAPTCHA is held in accordance with the Privacy Policy of Google: https://www.google.com/intl/en/policies/privacy/<br />\r\nGDPR Privacy<br />\r\nLegal Basis for Processing Personal Data under GDPR<br />\r\nWe may process Personal Data under the following conditions:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Consent: You have given Your consent for processing Personal Data for one or more specific purposes.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Performance of a contract: Provision of Personal Data is necessary for the performance of an agreement with You and/or for any pre-contractual obligations thereof.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Legal obligations: Processing Personal Data is necessary for compliance with a legal obligation to which the Company is subject.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Vital interests: Processing Personal Data is necessary in order to protect Your vital interests or of another natural person.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Public interests: Processing Personal Data is related to a task that is carried out in the public interest or in the exercise of official authority vested in the Company.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Legitimate interests: Processing Personal Data is necessary for the purposes of the legitimate interests pursued by the Company.<br />\r\nIn any case, the Company will gladly help to clarify the specific legal basis that applies to the processing, and in particular whether the provision of Personal Data is a statutory or contractual requirement, or a requirement necessary to enter into a contract.<br />\r\nYour Rights under the GDPR<br />\r\nThe Company undertakes to respect the confidentiality of Your Personal Data and to guarantee You can exercise Your rights.<br />\r\nYou have the right under this Privacy Policy, and by law if You are within the EU, to:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Request access to Your Personal Data. The right to access, update or delete the information We have on You. Whenever made possible, you can access, update or request deletion of Your Personal Data directly within Your account settings section. If you are unable to perform these actions yourself, please contact Us to assist You. This also enables You to receive a copy of the Personal Data We hold about You.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Request correction of the Personal Data that We hold about You. You have the right to have any incomplete or inaccurate information We hold about You corrected.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Object to processing of Your Personal Data. This right exists where We are relying on a legitimate interest as the legal basis for Our processing and there is something about Your particular situation, which makes You want to object to our processing of Your Personal Data on this ground. You also have the right to object where We are processing Your Personal Data for direct marketing purposes.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Request erasure of Your Personal Data. You have the right to ask Us to delete or remove Personal Data when there is no good reason for Us to continue processing it.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Request the transfer of Your Personal Data. We will provide to You, or to a third-party You have chosen, Your Personal Data in a structured, commonly used, machine-readable format. Please note that this right only applies to automated information which You initially provided consent for Us to use or where We used the information to perform a contract with You.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Withdraw Your consent. You have the right to withdraw Your consent on using your Personal Data. If You withdraw Your consent, We may not be able to provide You with access to certain specific functionalities of the Service.<br />\r\nExercising of Your GDPR Data Protection Rights<br />\r\nYou may exercise Your rights of access, rectification, cancellation and opposition by contacting Us. Please note that we may ask You to verify Your identity before responding to such requests. If You make a request, We will try our best to respond to You as soon as possible.<br />\r\nYou have the right to complain to a Data Protection Authority about Our collection and use of Your Personal Data. For more information, if You are in the European Economic Area (EEA), please contact Your local data protection authority in the EEA.<br />\r\nFacebook Fan Page<br />\r\nData Controller for the Facebook Fan Page<br />\r\nThe Company is the Data Controller of Your Personal Data collected while using the Service. As operator of the Facebook Fan Page https://www.facebook.com/profile.php?id=61560505499886, the Company and the operator of the social network Facebook are Joint Controllers.<br />\r\nThe Company has entered into agreements with Facebook that define the terms for use of the Facebook Fan Page, among other things. These terms are mostly based on the Facebook Terms of Service: https://www.facebook.com/terms.php<br />\r\nVisit the Facebook Privacy Policy https://www.facebook.com/policy.php for more information about how Facebook manages Personal data or contact Facebook online, or by mail: Facebook, Inc. ATTN, Privacy Operations, 1601 Willow Road, Menlo Park, CA 94025, United States.<br />\r\nFacebook Insights<br />\r\nWe use the Facebook Insights function in connection with the operation of the Facebook Fan Page and on the basis of the GDPR, in order to obtain anonymized statistical data about Our users.<br />\r\nFor this purpose, Facebook places a Cookie on the device of the user visiting Our Facebook Fan Page. Each Cookie contains a unique identifier code and remains active for a period of two years, except when it is deleted before the end of this period.<br />\r\nFacebook receives, records and processes the information stored in the Cookie, especially when the user visits the Facebook services, services that are provided by other members of the Facebook Fan Page and services by other companies that use Facebook services.<br />\r\nFor more information on the privacy practices of Facebook, please visit Facebook Privacy Policy here: https://www.facebook.com/privacy/explanation<br />\r\nChildren&#39;s Privacy<br />\r\nOur Service does not address anyone under the age of 13. We do not knowingly collect personally identifiable information from anyone under the age of 13. If You are a parent or guardian and You are aware that Your child has provided Us with Personal Data, please contact Us. If We become aware that We have collected Personal Data from anyone under the age of 13 without verification of parental consent, We take steps to remove that information from Our servers.<br />\r\nIf We need to rely on consent as a legal basis for processing Your information and Your country requires consent from a parent, We may require Your parent&#39;s consent before We collect and use that information.<br />\r\nLinks to Other Websites<br />\r\nOur Service may contain links to other websites that are not operated by Us. If You click on a third party link, You will be directed to that third party&#39;s site. We strongly advise You to review the Privacy Policy of every site You visit.<br />\r\nWe have no control over and assume no responsibility for the content, privacy policies or practices of any third party sites or services.<br />\r\nChanges to this Privacy Policy<br />\r\nWe may update Our Privacy Policy from time to time. We will notify You of any changes by posting the new Privacy Policy on this page.<br />\r\nWe will let You know via email and/or a prominent notice on Our Service, prior to the change becoming effective and update the &quot;Last updated&quot; date at the top of this Privacy Policy.<br />\r\nYou are advised to review this Privacy Policy periodically for any changes. Changes to this Privacy Policy are effective when they are posted on this page.<br />\r\nContact Us<br />\r\nIf you have any questions about this Privacy Policy, You can contact us:<br />\r\nBy email: ebook@ticketvilla.eu<br />\r\nBy visiting this page on our website: https://ticketvilla.eu<br />\r\nBy phone number: +13474740085<br />\r\nBy mail: Dryadon, 1, Floor 1, 6041, Larnaca, Cyprus</p>', '<p>Privacy Policy<br />\r\nLast updated: June 10, 2024<br />\r\nThis Privacy Policy describes Our policies and procedures on the collection, use and disclosure of Your information when You use the Service and tells You about Your privacy rights and how the law protects You.<br />\r\nWe use Your Personal data to provide and improve the Service. By using the Service, You agree to the collection and use of information in accordance with this Privacy Policy.<br />\r\n<br />\r\nInterpretation and Definitions<br />\r\n<br />\r\nInterpretation<br />\r\nThe words of which the initial letter is capitalized have meanings defined under the following conditions. The following definitions shall have the same meaning regardless of whether they appear in singular or in plural.<br />\r\n<br />\r\nDefinitions<br />\r\nFor the purposes of this Privacy Policy:<br />\r\n<br />\r\nAccount means a unique account created for You to access our Service or parts of our Service.<br />\r\n<br />\r\nAffiliate means an entity that controls, is controlled by or is under common control with a party, where &quot;control&quot; means ownership of 50% or more of the shares, equity interest or other securities entitled to vote for election of directors or other managing authority.<br />\r\n<br />\r\nApplication refers to TicketVilla, the software program provided by the Company.<br />\r\nCompany (referred to as either &quot;the Company&quot;, &quot;We&quot;, &quot;Us&quot; or &quot;Our&quot; in this Agreement) refers to TICKETVILLA Ltd, Dryadon, 1, Floor 1, 6041, Larnaca, Cyprus.<br />\r\nFor the purpose of the GDPR, the Company is the Data Controller.<br />\r\n<br />\r\nCookies are small files that are placed on Your computer, mobile device or any other device by a website, containing the details of Your browsing history on that website among its many uses.<br />\r\n<br />\r\nCountry refers to: Cyprus<br />\r\n<br />\r\nData Controller, for the purposes of the GDPR (General Data Protection Regulation), refers to the Company as the legal person which alone or jointly with others determines the purposes and means of the processing of Personal Data.<br />\r\n<br />\r\nDevice means any device that can access the Service such as a computer, a cellphone or a digital tablet.<br />\r\n<br />\r\nFacebook Fan Page is a public profile named Ticket Villa specifically created by the Company on the Facebook social network, accessible from https://www.facebook.com/profile.php?id=61560505499886<br />\r\n<br />\r\nGDPR refers to EU General Data Protection Regulation.<br />\r\n<br />\r\nPersonal Data is any information that relates to an identified or identifiable individual.<br />\r\nFor the purposes of GDPR, Personal Data means any information relating to You such as a name, an identification number, location data, online identifier or to one or more factors specific to the physical, physiological, genetic, mental, economic, cultural or social identity.<br />\r\n<br />\r\nService refers to the Application or the Website or both.<br />\r\n<br />\r\nService Provider means any natural or legal person who processes the data on behalf of the Company. It refers to third-party companies or individuals employed by the Company to facilitate the Service, to provide the Service on behalf of the Company, to perform services related to the Service or to assist the Company in analyzing how the Service is used. For the purpose of the GDPR, Service Providers are considered Data Processors.<br />\r\n<br />\r\nThird-party Social Media Service refers to any website or any social network website through which a User can log in or create an account to use the Service.<br />\r\nUsage Data refers to data collected automatically, either generated by the use of the Service or from the Service infrastructure itself (for example, the duration of a page visit).<br />\r\n<br />\r\nWebsite refers to TicketVilla, accessible from https://ticketvilla.eu<br />\r\n<br />\r\nYou means the individual accessing or using the Service, or the company, or other legal entity on behalf of which such individual is accessing or using the Service, as applicable.<br />\r\nUnder GDPR, You can be referred to as the Data Subject or as the User as you are the individual using the Service.<br />\r\n<br />\r\nCollecting and Using Your Personal Data<br />\r\n<br />\r\nTypes of Data Collected<br />\r\n<br />\r\nPersonal Data<br />\r\nWhile using Our Service, We may ask You to provide Us with certain personally identifiable information that can be used to contact or identify You. Personally identifiable information may include, but is not limited to:<br />\r\nEmail address<br />\r\nFirst name and last name<br />\r\nPhone number<br />\r\nAddress, State, Province, ZIP/Postal code, City<br />\r\nBank account information in order to pay for products and/or services within the Service<br />\r\nUsage Data<br />\r\n<br />\r\nWhen You pay for a product and/or a service via bank transfer, We may ask You to provide information to facilitate this transaction and to verify Your identity. Such information may include, without limitation:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Date of birth<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Passport or National ID card<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Bank card statement<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Other information linking You to an address<br />\r\n<br />\r\nUsage Data<br />\r\nUsage Data is collected automatically when using the Service.<br />\r\nUsage Data may include information such as Your Device&#39;s Internet Protocol address (e.g. IP address), browser type, browser version, the pages of our Service that You visit, the time and date of Your visit, the time spent on those pages, unique device identifiers and other diagnostic data.<br />\r\nWhen You access the Service by or through a mobile device, We may collect certain information automatically, including, but not limited to, the type of mobile device You use, Your mobile device unique ID, the IP address of Your mobile device, Your mobile operating system, the type of mobile Internet browser You use, unique device identifiers and other diagnostic data.<br />\r\nWe may also collect information that Your browser sends whenever You visit our Service or when You access the Service by or through a mobile device.<br />\r\n<br />\r\nInformation from Third-Party Social Media Services<br />\r\nThe Company allows You to create an account and log in to use the Service through the following Third-party Social Media Services:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Google<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Facebook<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Instagram<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Twitter<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; LinkedIn<br />\r\nIf You decide to register through or otherwise grant us access to a Third-Party Social Media Service, We may collect Personal data that is already associated with Your Third-Party Social Media Service&#39;s account, such as Your name, Your email address, Your activities or Your contact list associated with that account.<br />\r\nYou may also have the option of sharing additional information with the Company through Your Third-Party Social Media Service&#39;s account. If You choose to provide such information and Personal Data, during registration or otherwise, You are giving the Company permission to use, share, and store it in a manner consistent with this Privacy Policy.<br />\r\n<br />\r\nInformation Collected while Using the Application<br />\r\nWhile using Our Application, in order to provide features of Our Application, We may collect, with Your prior permission:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Information regarding your location<br />\r\nWe use this information to provide features of Our Service, to improve and customize Our Service. The information may be uploaded to the Company&#39;s servers and/or a Service Provider&#39;s server or it may be simply stored on Your device.<br />\r\nYou can enable or disable access to this information at any time, through Your Device settings.<br />\r\n<br />\r\nTracking Technologies and Cookies<br />\r\nWe use Cookies and similar tracking technologies to track the activity on Our Service and store certain information. Tracking technologies used are beacons, tags, and scripts to collect and track information and to improve and analyze Our Service. The techno.<br />\r\n<br />\r\n. Cookies or Browser Cookies. A cookie is a small file placed on Your Device. You can instruct Your browser to refuse all Cookies or to indicate when a Cookie is being sent. However, if You do not accept Cookies, You may not be able to use some parts of our Service. Unless you have adjusted Your browser setting so that it<br />\r\nwill refuse Cookies, our Service may use Cookies.<br />\r\n<br />\r\n. Web Beacons. Certain sections of our Service and our emails may contain small electronic files known as web beacons (also referred to as clear gifs, pixel tags, and single-pixel gifs) that permit the Company, for example, to count users who have visited those pages or opened an email and for other related website statistics (for example, recording the popularity of a certain section and verifying system and server integrity).<br />\r\n<br />\r\nCookies can be &quot;Persistent&quot; or &quot;Session&quot; Cookies. Persistent Cookies remain on Your personal computer or mobile device when You go offline, while Session Cookies are deleted as soon as You close Your web browser. You can learn more about cookies on TermsFeed website article.<br />\r\nWe use both Session and Persistent Cookies for the purposes set out below:<br />\r\n<br />\r\nNecessary / Essential Cookies<br />\r\nType: Session Cookies<br />\r\nAdministered by: Us<br />\r\nPurpose: These Cookies are essential to provide You with services available through the Website and to enable You to use some of its features. They help to authenticate users and prevent fraudulent use of user accounts. Without these Cookies, the services that You have asked for cannot be provided, and We only use these Cookies to provide You with those services.<br />\r\n<br />\r\nCookies Policy / Notice Acceptance Cookies<br />\r\nType: Persistent Cookies<br />\r\nAdministered by: Us<br />\r\nPurpose: These Cookies identify if users have accepted the use of cookies on the Website.<br />\r\n<br />\r\nFunctionality Cookies<br />\r\nType: Persistent Cookies<br />\r\nAdministered by: Us<br />\r\nPurpose: These Cookies allow us to remember choices You make when You use the Website, such as remembering your login details or language preference. The purpose of these Cookies is to provide You with a more personal experience and to avoid You having to re-enter your preferences every time You use the Website.<br />\r\n<br />\r\nTracking and Performance Cookies<br />\r\nType: Persistent Cookies<br />\r\nAdministered by: Third-Parties<br />\r\nPurpose: These Cookies are used to track information about traffic to the Website and how users use the Website. The information gathered via these Cookies may directly or indirectly identify you as an individual visitor. This is because the information collected is typically linked to a pseudonymous identifier associated with the device you use to access the Website. We may also use these Cookies to test new pages, features or new functionality of the Website to see how our users react to them.<br />\r\nFor more information about the cookies we use and your choices regarding cookies, please visit our Cookies Policy or the Cookies section of our Privacy Policy.<br />\r\n<br />\r\nUse of Your Personal Data<br />\r\n<br />\r\nThe Company may use Personal Data for the fallowing<br />\r\n<br />\r\n. To provide and maintain our Service, including to monitor the usage of our Service.<br />\r\n<br />\r\n. To manage Your Account: to manage Your registration as a user of the Service. The Personal Data You provide can give You access to different functionalities of the Service that are available to You as a registered use<br />\r\n<br />\r\n. For the performance of a contract: the development, compliance and undertaking of the purchase contract for the products, items or services You have purchased or of any other contract with Us through the Service.<br />\r\n<br />\r\n. To contact You: To contact You by email, telephone calls, SMS, or other equivalent forms of electronic communication, such as a mobile application&#39;s push notifications regarding updates or informative communications related to the functionalities, products or contracted services, including the security updates, when necessary or reasonable for their implementation.<br />\r\n<br />\r\n. To provide You with news, special offers and general information about other goods, services and events which we offer that are similar to those that you have already purchased or enquired about unless You have opted not to receive such information.<br />\r\n<br />\r\n. To manage Your requests: To attend and manage Your requests to Us.<br />\r\n<br />\r\n. To deliver targeted advertising to You: We may use Your information to develop and display content and advertising (and work with third-party vendors who do so) tailored to Your interests and/or location and to measure its effectiveness.<br />\r\n<br />\r\n. For business transfers: We may use Your information to evaluate or conduct a merger, divestiture, restructuring, reorganization, dissolution, or other sale or transfer of some or all of Our assets, whether as a going concern or as part of bankruptcy, liquidation, or similar proceeding, in which Personal Data held by Us about our Service users is among the assets transferred.<br />\r\n<br />\r\n. For other purposes: We may use Your information for other purposes, such as data analysis, identifying usage trends, determining the effectiveness of our promotional campaigns and to evaluate and improve our Service, products, services, marketing and your experience.<br />\r\nWe may share Your personal information in the following situations:<br />\r\n<br />\r\n. With Service Providers: We may share Your personal information with Service Providers to monitor and analyze the use of our Service, to advertise on third party websites to You after You visited our Service, for payment processing, to contact You.<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<br />\r\n. For business transfers: We may share or transfer Your personal information in connection with, or during negotiations of, any merger, sale of Company assets, financing, or acquisition of all or a portion of Our business to another company.<br />\r\n<br />\r\n. With Affiliates: We may share Your information with Our affiliates, in which case we will require those affiliates to honor this Privacy Policy. Affiliates include Our parent company and any other subsidiaries, joint venture partners or other companies that We control or that are under common control with Us.<br />\r\n<br />\r\n. With business partners: We may share Your information with Our business partners to offer You certain products, services or promotions.<br />\r\n<br />\r\n. With other users: when You share personal information or otherwise interact in the public areas with other users, such information may be viewed by all users and may be publicly distributed outside. If You interact with other users or register through a Third-Party Social Media Service, Your contacts on the Third-Party Social Media Service may see Your name, profile, pictures and description of Your activity. Similarly, other users will be able to view descriptions of Your activity, communicate with You and view Your profile.<br />\r\n<br />\r\n. With Your consent: We may disclose Your personal information for any other purpose with Your consent.<br />\r\n<br />\r\n<br />\r\nRetention of Your Personal Data<br />\r\nThe Company will retain Your Personal Data only for as long as is necessary for the purposes set out in this Privacy Policy. We will retain and use Your Personal Data to the extent necessary to comply with our legal obligations (for example, if we are required to retain your data to comply with applicable laws), resolve disputes, and enforce our legal agreements and policies.<br />\r\nThe Company will also retain Usage Data for internal analysis purposes. Usage Data is generally retained for a shorter period of time, except when this data is used to strengthen the security or to improve the functionality of Our Service, or We are legally obligated to retain this data for longer time periods.<br />\r\n<br />\r\nTransfer of Your Personal Data<br />\r\nYour information, including Personal Data, is processed at the Company&#39;s operating offices and in any other places where the parties involved in the processing are located. It means that this information may be transferred to &mdash; and maintained on &mdash; computers located outside of Your state, province, country or other governmental jurisdiction where the data protection laws may differ than those from Your jurisdiction.<br />\r\nYour consent to this Privacy Policy followed by Your submission of such information represents Your agreement to that transfer.<br />\r\nThe Company will take all steps reasonably necessary to ensure that Your data is treated securely and in accordance with this Privacy Policy and no transfer of Your Personal Data will take place to an organization or a country unless there are adequate controls in place including the security of Your data and other personal information.<br />\r\n<br />\r\nDelete Your Personal Data<br />\r\nYou have the right to delete or request that We assist in deleting the Personal Data that We have collected about You.<br />\r\nOur Service may give You the ability to delete certain information about You from within the Service.<br />\r\nYou may update, amend, or delete Your information at any time by signing in to Your Account, if you have one, and visiting the account settings section that allows you to manage Your personal information. You may also contact Us to request access to, correct, or delete any personal information that You have provided to Us.<br />\r\nPlease note, however, that We may need to retain certain information when we have a legal obligation or lawful basis to do so.<br />\r\n<br />\r\nDisclosure of Your Personal Data<br />\r\n<br />\r\nBusiness Transactions<br />\r\nIf the Company is involved in a merger, acquisition or asset sale, Your Personal Data may be transferred. We will provide notice before Your Personal Data is transferred and becomes subject to a different Privacy Policy.<br />\r\nLaw enforcement<br />\r\nUnder certain circumstances, the Company may be required to disclose Your Personal Data if required to do so by law or in response to valid requests by public authorities (e.g. a court or a government agency).<br />\r\nOther legal requirements<br />\r\nThe Company may disclose Your Personal Data in the good faith belief that such action is necessary to:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Comply with a legal obligation<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Protect and defend the rights or property of the Company<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Prevent or investigate possible wrongdoing in connection with the Service<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Protect the personal safety of Users of the Service or the public<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Protect against legal liability<br />\r\nSecurity of Your Personal Data<br />\r\nThe security of Your Personal Data is important to Us, but remember that no method of transmission over the Internet, or method of electronic storage is 100% secure. While We strive to use commercially acceptable means to protect Your Personal Data, We cannot guarantee its absolute security.<br />\r\nDetailed Information on the Processing of Your Personal Data<br />\r\nThe Service Providers We use may have access to Your Personal Data. These third-party vendors collect, store, use, process and transfer information about Your activity on Our Service in accordance with their Privacy Policies.<br />\r\nAnalytics<br />\r\nWe may use third-party Service providers to monitor and analyze the use of our Service.<br />\r\nGoogle Analytics<br />\r\nGoogle Analytics is a web analytics service offered by Google that tracks and reports website traffic. Google uses the data collected to track and monitor the use of our Service. This data is shared with other Google services. Google may use the collected data to contextualize and personalize the ads of its own advertising network.<br />\r\nYou can opt-out of having made your activity on the Service available to Google Analytics by installing the Google Analytics opt-out browser add-on. The add-on prevents the Google Analytics JavaScript (ga.js, analytics.js and dc.js) from sharing information with Google Analytics about visits activity.<br />\r\nYou may opt-out of certain Google Analytics features through your mobile device settings, such as your device advertising settings or by following the instructions provided by Google in their Privacy Policy: https://policies.google.com/privacy<br />\r\nFor more information on the privacy practices of Google, please visit the Google Privacy &amp; Terms web page: https://policies.google.com/privacy<br />\r\nFirebase<br />\r\nFirebase is an analytics service provided by Google Inc.<br />\r\nYou may opt-out of certain Firebase features through your mobile device settings, such as your device advertising settings or by following the instructions provided by Google in their Privacy Policy: https://policies.google.com/privacy<br />\r\nWe also encourage you to review the Google&#39;s policy for safeguarding your data: https://support.google.com/analytics/answer/6004245<br />\r\nFor more information on what type of information Firebase collects, please visit the How Google uses data when you use our partners&#39; sites or apps webpage: https://policies.google.com/technologies/partner-sites<br />\r\nMatomo<br />\r\nMatomo is a web analytics service. You can visit their Privacy Policy page here: https://matomo.org/privacy-policy<br />\r\nClicky<br />\r\nClicky is a web analytics service. Read the Privacy Policy for Clicky here: https://clicky.com/terms<br />\r\nFlurry Analytics<br />\r\nFlurry Analytics service is provided by Yahoo! Inc.<br />\r\nYou can opt-out from Flurry Analytics service to prevent Flurry Analytics from using and sharing your information by visiting the Flurry&#39;s Opt-out page: https://developer.yahoo.com/flurry/end-user-opt-out/<br />\r\nFor more information on the privacy practices and policies of Yahoo!, please visit their Privacy Policy page: https://policies.yahoo.com/xa/en/yahoo/privacy/index.htm<br />\r\nUnity Analytics<br />\r\nUnity Analytics is provided by Unity Technologies.<br />\r\nUnity Analytics collects, stores, uses, processes, and transfers personal information to provide, operate, and improve Unity Technologies services, including personalized advertising services. For more information on what type of information Unity Technologies collects, please visit their Privacy Policy page: https://unity3d.com/legal/privacy-policy.<br />\r\nYou can prevent Unity Analytics from using your information by opting-out. To opt-out of Unity Analytics, please visit this page: https://unity3d.com/legal/privacy-policy<br />\r\nYou may opt-out of all personalized advertising by enabling privacy features on Your mobile device such as Limit Ad Tracking (iOS) and Opt Out of Ads Personalization (Android). See Your mobile device Help system for more information.<br />\r\nHotjar<br />\r\nTheir Privacy Policy can be viewed at https://www.hotjar.com/legal/policies/privacy/<br />\r\nMeta Pixel<br />\r\nTheir Privacy Policy can be viewed at https://sites.google.com/view/metapixel-privacypolicy/home<br />\r\nFacebook Pixel<br />\r\nTheir Privacy Policy can be viewed at https://www.facebook.com/privacy/policy/<br />\r\nFacebook Conversions<br />\r\nTheir Privacy Policy can be viewed at https://www.facebook.com/privacy/policy/<br />\r\nEmail Marketing<br />\r\nWe may use Your Personal Data to contact You with newsletters, marketing or promotional materials and other information that may be of interest to You. You may opt-out of receiving any, or all, of these communications from Us by following the unsubscribe link or instructions provided in any email We send or by contacting Us.<br />\r\nWe may use Email Marketing Service Providers to manage and send emails to You.<br />\r\nMailchimp<br />\r\nMailchimp is an email marketing sending service provided by The Rocket Science Group LLC.<br />\r\nFor more information on the privacy practices of Mailchimp, please visit their Privacy policy: https://mailchimp.com/legal/privacy/<br />\r\nIntercom<br />\r\nTheir Privacy Policy can be viewed at https://www.intercom.com/legal/privacy<br />\r\nZendesk<br />\r\nTheir Privacy Policy can be viewed at https://www.zendesk.com/company/agreements-and-terms/privacy-notice/#<br />\r\nPayments<br />\r\nWe may provide paid products and/or services within the Service. In that case, we may use third-party services for payment processing (e.g. payment processors).<br />\r\nWe will not store or collect Your payment card details. That information is provided directly to Our third-party payment processors whose use of Your personal information is governed by their Privacy Policy. These payment processors adhere to the standards set by PCI-DSS as managed by the PCI Security Standards Council, which is a joint effort of brands like Visa, Mastercard, American Express and Discover. PCI-DSS requirements help ensure the secure handling of payment information.<br />\r\nApple Store In-App Payments<br />\r\nTheir Privacy Policy can be viewed at https://www.apple.com/legal/privacy/en-ww/<br />\r\nGoogle Play In-App Payments<br />\r\nTheir Privacy Policy can be viewed at https://www.google.com/policies/privacy/<br />\r\nStripe<br />\r\nTheir Privacy Policy can be viewed at https://stripe.com/us/privacy<br />\r\nShopify<br />\r\nTheir Privacy Policy can be viewed at https://www.shopify.com/legal/privacy<br />\r\nPayPal<br />\r\nTheir Privacy Policy can be viewed at https://www.paypal.com/webapps/mpp/ua/privacy-full<br />\r\nAlipay<br />\r\nTheir Privacy Policy can be viewed at https://render.alipay.com/p/f/agreementpages/alipayglobalprivacypolicy.html<br />\r\nAmazon Pay<br />\r\nTheir Privacy Policy can be viewed at https://www.amazon.in/gp/help/customer/display.html?nodeId=202136010<br />\r\nWhen You use Our Service to pay a product and/or service via bank transfer, We may ask You to provide information to facilitate this transaction and to verify Your identity.<br />\r\nBehavioral Remarketing<br />\r\nThe Company uses remarketing services to advertise to You after You accessed or visited our Service. We and Our third-party vendors use cookies and non-cookie technologies to help Us recognize Your Device and understand how You use our Service so that We can improve our Service to reflect Your interests and serve You advertisements that are likely to be of more interest to You.<br />\r\nThese third-party vendors collect, store, use, process and transfer information about Your activity on Our Service in accordance with their Privacy Policies and to enable Us to:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Measure and analyze traffic and browsing activity on Our Service<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Show advertisements for our products and/or services to You on third-party websites or apps<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Measure and analyze the performance of Our advertising campaigns<br />\r\nSome of these third-party vendors may use non-cookie technologies that may not be impacted by browser settings that block cookies. Your browser may not permit You to block such technologies. You can use the following third-party tools to decline the collection and use of information for the purpose of serving You interest-based advertising:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; The NAI&#39;s opt-out platform: http://www.networkadvertising.org/choices/<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; The EDAA&#39;s opt-out platform http://www.youronlinechoices.com/<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; The DAA&#39;s opt-out platform: http://optout.aboutads.info/?c=2&amp;lang=EN<br />\r\nYou may opt-out of all personalized advertising by enabling privacy features on Your mobile device such as Limit Ad Tracking (iOS) and Opt Out of Ads Personalization (Android). See Your mobile device Help system for more information.<br />\r\nWe may share information, such as hashed email addresses (if available) or other online identifiers collected on Our Service with these third-party vendors. This allows Our third-party vendors to recognize and deliver You ads across devices and browsers. To read more about the technologies used by these third-party vendors and their cross-device capabilities please refer to the Privacy Policy of each vendor listed below.<br />\r\nThe third-party vendors We use are:<br />\r\nGoogle Ads (AdWords)<br />\r\nGoogle Ads (AdWords) remarketing service is provided by Google Inc.<br />\r\nYou can opt-out of Google Analytics for Display Advertising and customize the Google Display Network ads by visiting the Google Ads Settings page: http://www.google.com/settings/ads<br />\r\nGoogle also recommends installing the Google Analytics Opt-out Browser Add-on - https://tools.google.com/dlpage/gaoptout - for your web browser. Google Analytics Opt-out Browser Add-on provides visitors with the ability to prevent their data from being collected and used by Google Analytics.<br />\r\nFor more information on the privacy practices of Google, please visit the Google Privacy &amp; Terms web page: https://policies.google.com/privacy<br />\r\nTwitter<br />\r\nTwitter remarketing service is provided by Twitter Inc.<br />\r\nYou can opt-out from Twitter&#39;s interest-based ads by following their instructions: https://support.twitter.com/articles/20170405<br />\r\nYou can learn more about the privacy practices and policies of Twitter by visiting their Privacy Policy page: https://twitter.com/privacy<br />\r\nFacebook<br />\r\nFacebook remarketing service is provided by Facebook Inc.<br />\r\nYou can learn more about interest-based advertising from Facebook by visiting this page: https://www.facebook.com/help/516147308587266<br />\r\nTo opt-out from Facebook&#39;s interest-based ads, follow these instructions from Facebook: https://www.facebook.com/help/568137493302217<br />\r\nFacebook adheres to the Self-Regulatory Principles for Online Behavioural Advertising established by the Digital Advertising Alliance. You can also opt-out from Facebook and other participating companies through the Digital Advertising Alliance in the USA http://www.aboutads.info/choices/, the Digital Advertising Alliance of Canada in Canada http://youradchoices.ca/ or the European Interactive Digital Advertising Alliance in Europe http://www.youronlinechoices.eu/, or opt-out using your mobile device settings.<br />\r\nFor more information on the privacy practices of Facebook, please visit Facebook&#39;s Data Policy: https://www.facebook.com/privacy/explanation<br />\r\nUsage, Performance and Miscellaneous<br />\r\nWe may use third-party Service Providers to maintain and improve our Service.<br />\r\nInvisible reCAPTCHA<br />\r\nWe use an invisible captcha service named reCAPTCHA. reCAPTCHA is operated by Google.<br />\r\nThe reCAPTCHA service may collect information from You and from Your Device for security purposes.<br />\r\nThe information gathered by reCAPTCHA is held in accordance with the Privacy Policy of Google: https://www.google.com/intl/en/policies/privacy/<br />\r\nGDPR Privacy<br />\r\nLegal Basis for Processing Personal Data under GDPR<br />\r\nWe may process Personal Data under the following conditions:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Consent: You have given Your consent for processing Personal Data for one or more specific purposes.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Performance of a contract: Provision of Personal Data is necessary for the performance of an agreement with You and/or for any pre-contractual obligations thereof.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Legal obligations: Processing Personal Data is necessary for compliance with a legal obligation to which the Company is subject.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Vital interests: Processing Personal Data is necessary in order to protect Your vital interests or of another natural person.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Public interests: Processing Personal Data is related to a task that is carried out in the public interest or in the exercise of official authority vested in the Company.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Legitimate interests: Processing Personal Data is necessary for the purposes of the legitimate interests pursued by the Company.<br />\r\nIn any case, the Company will gladly help to clarify the specific legal basis that applies to the processing, and in particular whether the provision of Personal Data is a statutory or contractual requirement, or a requirement necessary to enter into a contract.<br />\r\nYour Rights under the GDPR<br />\r\nThe Company undertakes to respect the confidentiality of Your Personal Data and to guarantee You can exercise Your rights.<br />\r\nYou have the right under this Privacy Policy, and by law if You are within the EU, to:<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Request access to Your Personal Data. The right to access, update or delete the information We have on You. Whenever made possible, you can access, update or request deletion of Your Personal Data directly within Your account settings section. If you are unable to perform these actions yourself, please contact Us to assist You. This also enables You to receive a copy of the Personal Data We hold about You.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Request correction of the Personal Data that We hold about You. You have the right to have any incomplete or inaccurate information We hold about You corrected.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Object to processing of Your Personal Data. This right exists where We are relying on a legitimate interest as the legal basis for Our processing and there is something about Your particular situation, which makes You want to object to our processing of Your Personal Data on this ground. You also have the right to object where We are processing Your Personal Data for direct marketing purposes.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Request erasure of Your Personal Data. You have the right to ask Us to delete or remove Personal Data when there is no good reason for Us to continue processing it.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Request the transfer of Your Personal Data. We will provide to You, or to a third-party You have chosen, Your Personal Data in a structured, commonly used, machine-readable format. Please note that this right only applies to automated information which You initially provided consent for Us to use or where We used the information to perform a contract with You.<br />\r\n&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Withdraw Your consent. You have the right to withdraw Your consent on using your Personal Data. If You withdraw Your consent, We may not be able to provide You with access to certain specific functionalities of the Service.<br />\r\nExercising of Your GDPR Data Protection Rights<br />\r\nYou may exercise Your rights of access, rectification, cancellation and opposition by contacting Us. Please note that we may ask You to verify Your identity before responding to such requests. If You make a request, We will try our best to respond to You as soon as possible.<br />\r\nYou have the right to complain to a Data Protection Authority about Our collection and use of Your Personal Data. For more information, if You are in the European Economic Area (EEA), please contact Your local data protection authority in the EEA.<br />\r\nFacebook Fan Page<br />\r\nData Controller for the Facebook Fan Page<br />\r\nThe Company is the Data Controller of Your Personal Data collected while using the Service. As operator of the Facebook Fan Page https://www.facebook.com/profile.php?id=61560505499886, the Company and the operator of the social network Facebook are Joint Controllers.<br />\r\nThe Company has entered into agreements with Facebook that define the terms for use of the Facebook Fan Page, among other things. These terms are mostly based on the Facebook Terms of Service: https://www.facebook.com/terms.php<br />\r\nVisit the Facebook Privacy Policy https://www.facebook.com/policy.php for more information about how Facebook manages Personal data or contact Facebook online, or by mail: Facebook, Inc. ATTN, Privacy Operations, 1601 Willow Road, Menlo Park, CA 94025, United States.<br />\r\nFacebook Insights<br />\r\nWe use the Facebook Insights function in connection with the operation of the Facebook Fan Page and on the basis of the GDPR, in order to obtain anonymized statistical data about Our users.<br />\r\nFor this purpose, Facebook places a Cookie on the device of the user visiting Our Facebook Fan Page. Each Cookie contains a unique identifier code and remains active for a period of two years, except when it is deleted before the end of this period.<br />\r\nFacebook receives, records and processes the information stored in the Cookie, especially when the user visits the Facebook services, services that are provided by other members of the Facebook Fan Page and services by other companies that use Facebook services.<br />\r\nFor more information on the privacy practices of Facebook, please visit Facebook Privacy Policy here: https://www.facebook.com/privacy/explanation<br />\r\nChildren&#39;s Privacy<br />\r\nOur Service does not address anyone under the age of 13. We do not knowingly collect personally identifiable information from anyone under the age of 13. If You are a parent or guardian and You are aware that Your child has provided Us with Personal Data, please contact Us. If We become aware that We have collected Personal Data from anyone under the age of 13 without verification of parental consent, We take steps to remove that information from Our servers.<br />\r\nIf We need to rely on consent as a legal basis for processing Your information and Your country requires consent from a parent, We may require Your parent&#39;s consent before We collect and use that information.<br />\r\nLinks to Other Websites<br />\r\nOur Service may contain links to other websites that are not operated by Us. If You click on a third party link, You will be directed to that third party&#39;s site. We strongly advise You to review the Privacy Policy of every site You visit.<br />\r\nWe have no control over and assume no responsibility for the content, privacy policies or practices of any third party sites or services.<br />\r\nChanges to this Privacy Policy<br />\r\nWe may update Our Privacy Policy from time to time. We will notify You of any changes by posting the new Privacy Policy on this page.<br />\r\nWe will let You know via email and/or a prominent notice on Our Service, prior to the change becoming effective and update the &quot;Last updated&quot; date at the top of this Privacy Policy.<br />\r\nYou are advised to review this Privacy Policy periodically for any changes. Changes to this Privacy Policy are effective when they are posted on this page.<br />\r\nContact Us<br />\r\nIf you have any questions about this Privacy Policy, You can contact us:<br />\r\nBy email: ebook@ticketvilla.eu<br />\r\nBy visiting this page on our website: https://ticketvilla.eu<br />\r\nBy phone number: +13474740085<br />\r\nBy mail: Dryadon, 1, Floor 1, 6041, Larnaca, Cyprus</p>', 'uploads/dynamic-page/1718529261-privacy-banner.png', 'active', '2024-06-16 03:14:21', '2024-06-17 22:56:07');
INSERT INTO `dynamic_pages` (`id`, `page_slug`, `title_en`, `title_de`, `title_hu`, `sub_title_en`, `sub_title_de`, `sub_title_hu`, `description_en`, `description_de`, `description_hu`, `image`, `status`, `created_at`, `updated_at`) VALUES
(3, 'terms-and-conditions', 'Terms and conditions', 'Terms and conditions', 'Terms and conditions', '<p>Protecting your privacy: Our Commitment to you</p>\r\n\r\n<div id=\"gtx-trans\" style=\"position: absolute; left: -123px; top: 38px;\">\r\n<div class=\"gtx-trans-icon\">&nbsp;</div>\r\n</div>', '<p>Protecting your privacy: Our Commitment to you</p>', '<p>Protecting your privacy: Our Commitment to you</p>', '<p>Terms of Service<br />\r\nThese terms and conditions (&ldquo;Agreement&rdquo;) set forth the general terms and conditions of your use of the ticketvilla.eu website (&ldquo;Website&rdquo; or &ldquo;Service&rdquo;) and any of its related products and services (collectively, &ldquo;Services&rdquo;). This Agreement is legally binding between you (&ldquo;User&rdquo;, &ldquo;you&rdquo; or &ldquo;your&rdquo;) and TICKETVILLA Ltd (doing business as &ldquo;TicketVilla&rdquo;, &ldquo;we&rdquo;, &ldquo;us&rdquo; or &ldquo;our&rdquo;). If you are entering into this Agreement on behalf of a business or other legal entity, you represent that you have the authority to bind such entity to this Agreement, in which case the terms &ldquo;User&rdquo;, &ldquo;you&rdquo; or &ldquo;your&rdquo; shall refer to such entity. If you do not have such authority, or if you do not agree with the terms of this Agreement, you must not accept this Agreement and may not access and use the Website and Services. By accessing and using the Website and Services, you acknowledge that you have read, understood, and agree to be bound by the terms of this Agreement. You acknowledge that this Agreement is a contract between you and TicketVilla, even though it is electronic and is not physically signed by you, and it governs your use of the Website and Services.<br />\r\nAccounts and membership<br />\r\nYou must be at least 18 years of age to use the Website and Services. By using the Website and Services and by agreeing to this Agreement you warrant and represent that you are at least 18 years of age. If you create an account on the Website, you are responsible for maintaining the security of your account and you are fully responsible for all activities that occur under the account and any other actions taken in connection with it. We may monitor and review new accounts before you may sign in and start using the Services. Providing false contact information of any kind may result in the termination of your account. You must immediately notify us of any unauthorized uses of your account or any other breaches of security. We will not be liable for any acts or omissions by you, including any damages of any kind incurred as a result of such acts or omissions. We may suspend, disable, or delete your account (or any part thereof) if we determine that you have violated any provision of this Agreement or that your conduct or content would tend to damage our reputation and goodwill. If we delete your account for the foregoing reasons, you may not re-register for our Services. We may block your email address and Internet protocol address to prevent further registration.<br />\r\nAdult content<br />\r\nPlease be aware that there may be certain adult or mature content available on the Website. A warning will be shown to the User prior to adult content being displayed. Where there is mature or adult content, individuals who are less than 18 years of age or are not permitted to access such content under the laws of any applicable jurisdiction may not access such content. If we learn that anyone under the age of 18 seeks to conduct a transaction through the Services, we will require verified parental consent, in accordance with the Children&rsquo;s Online Privacy Protection Act of 1998 (&ldquo;COPPA&rdquo;). Certain areas of the Website and Services may not be available to children under 18 under any circumstances.<br />\r\nBilling and payments<br />\r\nYou shall pay all fees or charges to your account in accordance with the fees, charges, and billing terms in effect at the time a fee or charge is due and payable. Sensitive and private data exchange happens over a SSL secured communication channel and is encrypted and protected with digital signatures, and the Website and Services are also in compliance with PCI vulnerability standards in order to create as secure of an environment as possible for Users. Scans for malware are performed on a regular basis for additional security and protection. If, in our judgment, your purchase constitutes a high-risk transaction, we will require you to provide us with a copy of your valid government-issued photo identification, and possibly a copy of a recent bank statement for the credit or debit card used for the purchase. We reserve the right to change products and product pricing at any time. We also reserve the right to refuse any order you place with us. We may, in our sole discretion, limit or cancel quantities purchased per person, per household or per order. These restrictions may include orders placed by or under the same customer account, the same credit card, and/or orders that use the same billing and/or shipping address. In the event that we make a change to or cancel an order, we may attempt to notify you by contacting the e-mail and/or billing address/phone number provided at the time the order was made.<br />\r\nAccuracy of information<br />\r\nOccasionally there may be information on the Website that contains typographical errors, inaccuracies or omissions that may relate to promotions and offers. We reserve the right to correct any errors, inaccuracies or omissions, and to change or update information or cancel orders if any information on the Website or Services is inaccurate at any time without prior notice (including after you have submitted your order). We undertake no obligation to update, amend or clarify information on the Website including, without limitation, pricing information, except as required by law. No specified update or refresh date applied on the Website should be taken to indicate that all information on the Website or Services has been modified or updated.<br />\r\nThird party services<br />\r\nIf you decide to enable, access or use third party services, be advised that your access and use of such other services are governed solely by the terms and conditions of such other services, and we do not endorse, are not responsible or liable for, and make no representations as to any aspect of such other services, including, without limitation, their content or the manner in which they handle data (including your data) or any interaction between you and the provider of such other services. You irrevocably waive any claim against TicketVilla with respect to such other services. TicketVilla is not liable for any damage or loss caused or alleged to be caused by or in connection with your enablement, access or use of any such other services, or your reliance on the privacy practices, data security processes or other policies of such other services. You may be required to register for or log into such other services on their respective platforms. By enabling any other services, you are expressly permitting TicketVilla to disclose your data as necessary to facilitate the use or enablement of such other service.<br />\r\nLinks to other resources<br />\r\nAlthough the Website and Services may link to other resources (such as websites, mobile applications, etc.), we are not, directly or indirectly, implying any approval, association, sponsorship, endorsement, or affiliation with any linked resource, unless specifically stated herein. Some of the links on the Website may be &ldquo;affiliate links&rdquo;. This means if you click on the link and purchase an item, TicketVilla will receive an affiliate commission. We are not responsible for examining or evaluating, and we do not warrant the offerings of, any businesses or individuals or the content of their resources. We do not assume any responsibility or liability for the actions, products, services, and content of any other third parties. You should carefully review the legal statements and other conditions of use of any resource which you access through a link on the Website. Your linking to any other off-site resources is at your own risk.<br />\r\nRaffle Rules<br />\r\nBy purchasing an eBook from www.ticketvilla.eu, you irrevocably accept the &quot;Raffle Rules&quot;, &quot;Terms of Services&quot;, &quot;Privacy Policy&quot;, &quot;Imprint&quot; by clicking on the &quot;Buy Now&quot; or &quot;Sign Up&quot; (Registration) buttons on the site.<br />\r\n&nbsp;<br />\r\nIf the buyer breaches any of these rules, TICKETVILLA Ltd shall be entitled to terminate the contractual relationship with the buyer without any obligation to pay any compensation and exclude the buyer from the draws and competitions related to the eBook purchase.<br />\r\nProhibited uses<br />\r\nIn addition to other terms as set forth in the Agreement, you are prohibited from using the Website and Services or Content: (a) for any unlawful purpose; (b) to solicit others to perform or participate in any unlawful acts; (c) to violate any international, federal, provincial or state regulations, rules, laws, or local ordinances; (d) to infringe upon or violate our intellectual property rights or the intellectual property rights of others; (e) to harass, abuse, insult, harm, defame, slander, disparage, intimidate, or discriminate based on gender, sexual orientation, religion, ethnicity, race, age, national origin, or disability; (f) to submit false or misleading information; (g) to upload or transmit viruses or any other type of malicious code that will or may be used in any way that will affect the functionality or operation of the Website and Services, third party products and services, or the Internet; (h) to spam, phish, pharm, pretext, spider, crawl, or scrape; (i) for any obscene or immoral purpose; or (j) to interfere with or circumvent the security features of the Website and Services, third party products and services, or the Internet. We reserve the right to terminate your use of the Website and Services for violating any of the prohibited uses.<br />\r\nIntellectual property rights<br />\r\n&ldquo;Intellectual Property Rights&rdquo; means all present and future rights conferred by statute, common law or equity in or in relation to any copyright and related rights, trademarks, designs, patents, inventions, goodwill and the right to sue for passing off, rights to inventions, rights to use, and all other intellectual property rights, in each case whether registered or unregistered and including all applications and rights to apply for and be granted, rights to claim priority from, such rights and all similar or equivalent rights or forms of protection and any other results of intellectual activity which subsist or will subsist now or in the future in any part of the world. This Agreement does not transfer to you any intellectual property owned by TicketVilla or third parties, and all rights, titles, and interests in and to such property will remain (as between the parties) solely with TicketVilla. All trademarks, service marks, graphics and logos used in connection with the Website and Services, are trademarks or registered trademarks of TicketVilla or its licensors. Other trademarks, service marks, graphics and logos used in connection with the Website and Services may be the trademarks of other third parties. Your use of the Website and Services grants you no right or license to reproduce or otherwise use any of TicketVilla or third party trademarks.<br />\r\nDisclaimer of warranty<br />\r\nYou agree that such Service is provided on an &ldquo;as is&rdquo; and &ldquo;as available&rdquo; basis and that your use of the Website and Services is solely at your own risk. We expressly disclaim all warranties of any kind, whether express or implied, including but not limited to the implied warranties of merchantability, fitness for a particular purpose and non-infringement. We make no warranty that the Services will meet your requirements, or that the Service will be uninterrupted, timely, secure, or error-free; nor do we make any warranty as to the results that may be obtained from the use of the Service or as to the accuracy or reliability of any information obtained through the Service or that defects in the Service will be corrected. You understand and agree that any material and/or data downloaded or otherwise obtained through the use of Service is done at your own discretion and risk and that you will be solely responsible for any damage or loss of data that results from the download of such material and/or data. We make no warranty regarding any goods or services purchased or obtained through the Service or any transactions entered into through the Service unless stated otherwise. No advice or information, whether oral or written, obtained by you from us or through the Service shall create any warranty not expressly made herein.<br />\r\nLimitation of liability<br />\r\nTo the fullest extent permitted by applicable law, in no event will TicketVilla, its affiliates, directors, officers, employees, agents, suppliers or licensors be liable to any person for any indirect, incidental, special, punitive, cover or consequential damages (including, without limitation, damages for lost profits, revenue, sales, goodwill, use of content, impact on business, business interruption, loss of anticipated savings, loss of business opportunity) however caused, under any theory of liability, including, without limitation, contract, tort, warranty, breach of statutory duty, negligence or otherwise, even if the liable party has been advised as to the possibility of such damages or could have foreseen such damages. To the maximum extent permitted by applicable law, the aggregate liability of TicketVilla and its affiliates, officers, employees, agents, suppliers and licensors relating to the services will be limited to an amount no greater than one dollar or any amounts actually paid in cash by you to TicketVilla for the prior one month period prior to the first event or occurrence giving rise to such liability. The limitations and exclusions also apply if this remedy does not fully compensate you for any losses or fails of its essential purpose.<br />\r\nIndemnification<br />\r\nYou agree to indemnify and hold TicketVilla and its affiliates, directors, officers, employees, agents, suppliers and licensors harmless from and against any liabilities, losses, damages or costs, including reasonable attorneys&rsquo; fees, incurred in connection with or arising from any third party allegations, claims, actions, disputes, or demands asserted against any of them as a result of or relating to your Content, your use of the Website and Services or any willful misconduct on your part.<br />\r\nSeverability<br />\r\nAll rights and restrictions contained in this Agreement may be exercised and shall be applicable and binding only to the extent that they do not violate any applicable laws and are intended to be limited to the extent necessary so that they will not render this Agreement illegal, invalid or unenforceable. If any provision or portion of any provision of this Agreement shall be held to be illegal, invalid or unenforceable by a court of competent jurisdiction, it is the intention of the parties that the remaining provisions or portions thereof shall constitute their agreement with respect to the subject matter hereof, and all such remaining provisions or portions thereof shall remain in full force and effect.<br />\r\nDispute resolution<br />\r\nThe formation, interpretation, and performance of this Agreement and any disputes arising out of it shall be governed by the substantive and procedural laws of Cyprus without regard to its rules on conflicts or choice of law and, to the extent applicable, the laws of Cyprus. The exclusive jurisdiction and venue for actions related to the subject matter hereof shall be the courts located in Cyprus, and you hereby submit to the personal jurisdiction of such courts. You hereby waive any right to a jury trial in any proceeding arising out of or related to this Agreement. The United Nations Convention on Contracts for the International Sale of Goods does not apply to this Agreement.<br />\r\nAssignment<br />\r\nYou may not assign, resell, sub-license or otherwise transfer or delegate any of your rights or obligations hereunder, in whole or in part, without our prior written consent, which consent shall be at our own sole discretion and without obligation; any such assignment or transfer shall be null and void. We are free to assign any of its rights or obligations hereunder, in whole or in part, to any third party as part of the sale of all or substantially all of its assets or stock or as part of a merger.<br />\r\nChanges and amendments<br />\r\nWe reserve the right to modify this Agreement or its terms related to the Website and Services at any time at our discretion. When we do, we will revise the updated date at the bottom of this page, post a notification on the main page of the Website. We may also provide notice to you in other ways at our discretion, such as through the contact information you have provided.<br />\r\n&nbsp;<br />\r\nAn updated version of this Agreement will be effective immediately upon the posting of the revised Agreement unless otherwise specified. Your continued use of the Website and Services after the effective date of the revised Agreement (or such other act specified at that time) will constitute your consent to those changes.<br />\r\nAcceptance of these terms<br />\r\nYou acknowledge that you have read this Agreement and agree to all its terms and conditions. By accessing and using the Website and Services you agree to be bound by this Agreement. If you do not agree to abide by the terms of this Agreement, you are not authorized to access or use the Website and Services.<br />\r\nContacting us<br />\r\nIf you have any questions, concerns, or complaints regarding this Agreement, we encourage you to contact us using the details below:<br />\r\n&nbsp;<br />\r\nhttps://ticketvilla.eu/contact<br />\r\nebook@ticketvilla.eu<br />\r\nDryadon, 1, Floor 1, 6041, Larnaca, Cyprus</p>', '<p>Terms of Service<br />\r\nThese terms and conditions (&ldquo;Agreement&rdquo;) set forth the general terms and conditions of your use of the ticketvilla.eu website (&ldquo;Website&rdquo; or &ldquo;Service&rdquo;) and any of its related products and services (collectively, &ldquo;Services&rdquo;). This Agreement is legally binding between you (&ldquo;User&rdquo;, &ldquo;you&rdquo; or &ldquo;your&rdquo;) and TICKETVILLA Ltd (doing business as &ldquo;TicketVilla&rdquo;, &ldquo;we&rdquo;, &ldquo;us&rdquo; or &ldquo;our&rdquo;). If you are entering into this Agreement on behalf of a business or other legal entity, you represent that you have the authority to bind such entity to this Agreement, in which case the terms &ldquo;User&rdquo;, &ldquo;you&rdquo; or &ldquo;your&rdquo; shall refer to such entity. If you do not have such authority, or if you do not agree with the terms of this Agreement, you must not accept this Agreement and may not access and use the Website and Services. By accessing and using the Website and Services, you acknowledge that you have read, understood, and agree to be bound by the terms of this Agreement. You acknowledge that this Agreement is a contract between you and TicketVilla, even though it is electronic and is not physically signed by you, and it governs your use of the Website and Services.<br />\r\nAccounts and membership<br />\r\nYou must be at least 18 years of age to use the Website and Services. By using the Website and Services and by agreeing to this Agreement you warrant and represent that you are at least 18 years of age. If you create an account on the Website, you are responsible for maintaining the security of your account and you are