lluminate/Container/Container.php(662): Illuminate\\Container\\BoundMethod::call()\n#37 /home/reigeeky/ticket-villa.reigeeky.com/vendor/laravel/framework/src/Illuminate/Console/Command.php(211): Illuminate\\Container\\Container->call()\n#38 /home/reigeeky/ticket-villa.reigeeky.com/vendor/symfony/console/Command/Command.php(326): Illuminate\\Console\\Command->execute()\n#39 /home/reigeeky/ticket-villa.reigeeky.com/vendor/laravel/framework/src/Illuminate/Console/Command.php(180): Symfony\\Component\\Console\\Command\\Command->run()\n#40 /home/reigeeky/ticket-villa.reigeeky.com/vendor/symfony/console/Application.php(1096): Illuminate\\Console\\Command->run()\n#41 /home/reigeeky/ticket-villa.reigeeky.com/vendor/symfony/console/Application.php(324): Symfony\\Component\\Console\\Application->doRunCommand()\n#42 /home/reigeeky/ticket-villa.reigeeky.com/vendor/symfony/console/Application.php(175): Symfony\\Component\\Console\\Application->doRun()\n#43 /home/reigeeky/ticket-villa.reigeeky.com/vendor/laravel/framework/src/Illuminate/Foundation/Console/Kernel.php(201): Symfony\\Component\\Console\\Application->run()\n#44 /home/reigeeky/ticket-villa.reigeeky.com/artisan(35): Illuminate\\Foundation\\Console\\Kernel->handle()\n#45 {main}', '2024-06-19 22:19:49');

