--
-- Table structure for table `f_a_q_s`
--

CREATE TABLE `f_a_q_s` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `question_en` varchar(255) DEFAULT NULL,
  `question_de` varchar(255) DEFAULT NULL,
  `question_hu` varchar(255) DEFAULT NULL,
  `answer_en` text DEFAULT NULL,
  `answer_de` text DEFAULT NULL,
  `answer_hu` text DEFAULT NULL,
  `status` enum('active','inactive') NOT NULL DEFAULT 'active',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `f_a_q_s`
--

INSERT INTO `f_a_q_s` (`id`, `question_en`, `question_de`, `question_hu`, `answer_en`, `answer_de`, `answer_hu`, `status`, `created_at`, `updated_at`) VALUES
(1, 'How does the house raffle work?', 'Wie funktioniert die Häuserverlosung?', 'Hogyan működik a házi sorsolás?', '<p>Purchase the Styria 2024 eBook at www.ticketvilla.eu and for every eBook you buy, you will receive a ticket to enter the draw for the Styria 2024 Family State House in Austria. All the details are on the website, but you can also watch a short animation explaining how it works at the link below: Link</p>', '<p>Kaufen Sie das eBook &bdquo;Styria 2024&ldquo; unter www.ticketvilla.eu und f&uuml;r jedes eBook, das Sie kaufen, erhalten Sie ein Ticket f&uuml;r die Verlosung des Familienlandeshauses &bdquo;Styria 2024&ldquo; in &Ouml;sterreich. Alle Einzelheiten finden Sie auf der Website, aber Sie k&ouml;nnen sich auch eine kurze Animation ansehen, die erkl&auml;rt, wie es funktioniert, unter dem folgenden Link: Link</p>', '<p>V&aacute;s&aacute;rolja meg a St&aacute;jerorsz&aacute;g 2024 e-k&ouml;nyvet a www.ticketvilla.eu oldalon, &eacute;s minden megv&aacute;s&aacute;rolt e-k&ouml;nyv ut&aacute;n jegyet kap, amellyel r&eacute;szt vehet az ausztriai St&aacute;jerorsz&aacute;g 2024 Csal&aacute;di &Aacute;llami H&aacute;z sorsol&aacute;s&aacute;n. Minden r&eacute;szlet megtal&aacute;lhat&oacute; a weboldalon, de az al&aacute;bbi linken megtekinthet egy r&ouml;vid anim&aacute;ci&oacute;t is, amely elmagyar&aacute;zza ennek műk&ouml;d&eacute;s&eacute;t: Link</p>', 'active', '2024-06-15 03:45:28', '2024-06-15 03:45:28'),
(2, 'How is the winner selected and notified?', 'Wie wird der Gewinner ausgewählt und benachrichtigt?', 'Hogyan történik a nyertes kiválasztása és értesítése?', '<p>The winner will be drawn by a Cypriot notary and will be notified using the details provided at the time of purchase (name, postal address, e-mail, telephone). The winner will also be named live on the website, based on the serial number assigned to him/her in our database, and his/her name will be displayed on the website so that he/she can search for our company.</p>', '<p>Der Gewinner wird von einem zypriotischen Notar ausgelost und anhand der beim Kauf angegebenen Daten (Name, Postanschrift, E-Mail, Telefon) benachrichtigt. Der Gewinner wird au&szlig;erdem live auf der Website anhand der ihm/ihr in unserer Datenbank zugewiesenen Seriennummer bekannt gegeben und sein/ihr Name wird auf der Website angezeigt, damit er/sie nach unserem Unternehmen suchen kann.</p>', '<p>A nyertest egy ciprusi k&ouml;zjegyző sorsolja ki, &eacute;s a v&aacute;s&aacute;rl&aacute;skor megadott adatokon (n&eacute;v, postac&iacute;m, e-mail, telefon) &eacute;rtes&iacute;ti. A nyertest az adatb&aacute;zisunkban hozz&aacute;rendelt sorsz&aacute;m alapj&aacute;n a honlapon &eacute;lőben is megnevezz&uuml;k, nev&eacute;t a honlapon megjelen&iacute;tj&uuml;k, hogy r&aacute;kereshessen c&eacute;g&uuml;nkre.</p>', 'active', '2024-06-15 03:46:16', '2024-06-15 03:46:16'),
(3, 'Can I participate in the raffle from any country?', 'Kann ich von jedem Land aus an der Verlosung teilnehmen?', 'Bármely országból részt vehetek a sorsoláson?', '<p>Yes, any non-sanctioned person or company from any non-sanctioned country can participate.</p>', '<p>Ja, jede nicht sanktionierte Person oder Firma aus jedem nicht sanktionierten Land kann teilnehmen.</p>', '<p>Igen, b&aacute;rmely nem szankcion&aacute;lt szem&eacute;ly vagy c&eacute;g b&aacute;rmely nem szankcion&aacute;lt orsz&aacute;gb&oacute;l r&eacute;szt vehet.</p>', 'active', '2024-06-15 03:47:42', '2024-06-15 03:47:42'),
(4, 'Is there a limit to how many tickets I can purchase?', 'Gibt es eine Begrenzung für die Anzahl der Tickets, die ich kaufen kann?', 'Van-e korlátja annak, hogy hány jegyet vásárolhatok?', '<p>No, we do not limit the number of tickets that can be purchased, as this would reduce the chances of our eBook customers winning.</p>', '<p>Nein, wir begrenzen die Anzahl der kaufbaren Lose nicht, da dies die Gewinnchancen unserer eBook-Kunden verringern w&uuml;rde.</p>', '<p>Nem, nem korl&aacute;tozzuk a megv&aacute;s&aacute;rolhat&oacute; jegyek sz&aacute;m&aacute;t, mert ezzel cs&ouml;kkenten&eacute; eBook v&aacute;s&aacute;rl&oacute;ink ​​nyer&eacute;si es&eacute;lyeit.</p>', 'active', '2024-06-15 03:49:02', '2024-06-15 03:49:02'),
(5, 'What happens if the minimum number of tickets isn´t sold?', 'Was passiert, wenn die Mindestanzahl an Tickets nicht verkauft wird?', 'Mi történik, ha a minimális számú jegyet nem adják el?', '<p>This will not happen, as we will make our eBook sales available in every country in the world, and if necessary we will change our marketing to encourage sales.</p>', '<p>Dies wird nicht passieren, da wir den Verkauf unseres E-Books in jedem Land der Welt erm&ouml;glichen und bei Bedarf unser Marketing &auml;ndern werden, um den Verkauf anzukurbeln.</p>', '<p>Ez nem fog megt&ouml;rt&eacute;nni, hiszen a vil&aacute;g minden orsz&aacute;g&aacute;ban el&eacute;rhetőv&eacute; tessz&uuml;k e-k&ouml;nyv-&eacute;rt&eacute;kes&iacute;t&eacute;s&uuml;nket, &eacute;s ha sz&uuml;ks&eacute;ges, az &eacute;rt&eacute;kes&iacute;t&eacute;s &ouml;szt&ouml;nz&eacute;se &eacute;rdek&eacute;ben megv&aacute;ltoztatjuk marketing&uuml;nket.</p>', 'active', '2024-06-15 03:50:21', '2024-06-15 03:50:21'),
(6, 'Are there any additional costs for the house winner, such as taxes or fees?', 'Entstehen für den Hausgewinner zusätzliche Kosten, wie etwa Steuern oder Gebühren?', 'Vannak-e további költségek a ház nyertesének, például adók vagy illetékek?', '<p>No, the Austrian legal and public costs of buying the house and taking ownership are paid by the Cypriot company (TicketVilla Ltd.).</p>', '<p>Nein, die &ouml;sterreichischen Rechts- und &ouml;ffentlichen Kosten f&uuml;r den Hauskauf und die Eigentums&uuml;bernahme werden von der zypriotischen Firma (TicketVilla Ltd.) getragen.</p>', '<p>Nem, a h&aacute;z megv&aacute;s&aacute;rl&aacute;s&aacute;nak &eacute;s tulajdonba v&eacute;tel&eacute;nek osztr&aacute;k jogi &eacute;s k&ouml;zk&ouml;lts&eacute;geit a ciprusi c&eacute;g (TicketVilla Ltd.) fizeti.</p>', 'active', '2024-06-15 03:51:09', '2024-06-15 03:51:09'),
(7, 'How is the property transferred to the winner?', 'Wie wird das Eigentum an den Gewinner übertragen?', 'Hogyan kerül át az ingatlan a nyertesre?', '<p>The contract for the sale of the property must be signed in front of an Austrian notary, the cost of travel to the property is paid for by the Cypriot company in the economy class of commercial flights and the cost of accommodation for the duration of the transaction is paid by the Cypriot company. The winner will then be able to collect the two additional prizes (EUR 20.000,- XXXLutz voucher and EUR 60.000,- swimming pool) in Cyprus from the Cypriot notary public if they request them in cash, with travel expenses in economy class on commercial flights and accommodation for the duration of the transaction paid by the Cypriot company.</p>', '<p>Der Kaufvertrag f&uuml;r die Immobilie muss vor einem &ouml;sterreichischen Notar unterzeichnet werden, die Reisekosten zur Immobilie werden von der zypriotischen Firma in der Economy Class kommerzieller Fl&uuml;ge &uuml;bernommen und die Kosten f&uuml;r die Unterkunft f&uuml;r die Dauer der Transaktion werden von der zypriotischen Firma &uuml;bernommen. Der Gewinner kann dann die beiden zus&auml;tzlichen Preise (20.000,- EUR XXXLutz-Gutschein und 60.000,- EUR Swimmingpool) in Zypern beim zypriotischen Notar abholen, wenn er diese in bar verlangt, wobei die Reisekosten in der Economy Class kommerzieller Fl&uuml;ge und die Unterkunft f&uuml;r die Dauer der Transaktion von der zypriotischen Firma &uuml;bernommen werden.</p>', '<p>Az ingatlan ad&aacute;sv&eacute;teli szerződ&eacute;s&eacute;t osztr&aacute;k k&ouml;zjegyző előtt kell al&aacute;&iacute;rni, az ingatlanhoz val&oacute; utaz&aacute;s k&ouml;lts&eacute;g&eacute;t a kereskedelmi j&aacute;ratok turistaoszt&aacute;ly&aacute;n a ciprusi c&eacute;g fizeti, valamint a sz&aacute;ll&aacute;s k&ouml;lts&eacute;g&eacute;t a tranzakci&oacute; időtartam&aacute;ra. a ciprusi c&eacute;g fizeti. A nyertes ezut&aacute;n &aacute;tveheti a k&eacute;t tov&aacute;bbi nyerem&eacute;nyt (20.000 EUR XXXLutz-utalv&aacute;ny &eacute;s 60.000 EUR &uacute;sz&oacute;medence) Cipruson a ciprusi k&ouml;zjegyzőtől, ha k&eacute;szp&eacute;nzben k&eacute;ri, utaz&aacute;si k&ouml;lts&eacute;ggel egy&uuml;tt turistaoszt&aacute;lyon kereskedelmi j&aacute;ratok eset&eacute;n. &eacute;s sz&aacute;ll&aacute;st a tranzakci&oacute; időtartam&aacute;ra a ciprusi c&eacute;g fizet.</p>', 'active', '2024-06-15 03:52:43', '2024-06-15 03:52:43'),
(8, 'Where is TicketVilla Ltd. based?', 'Wo ist TicketVilla Ltd. ansässig?', 'Hol található a TicketVilla Kft.?', '<p>We&#39;re a Cypern-based company. Our Head Office address is:</p>\r\n\r\n<p>TicketVilla Ltd</p>\r\n\r\n<p>Dryadon, 1,</p>\r\n\r\n<p>Floor 1,</p>\r\n\r\n<p>6041, Larnaca, Cyprus.</p>', '<p>Wir sind ein in Zypern ans&auml;ssiges Unternehmen. Die Adresse unseres Hauptsitzes lautet:<br />\r\nTicketVilla Ltd<br />\r\nDryadon, 1,<br />\r\nStockwerk 1,<br />\r\n6041, Larnaca, Zypern.</p>', '<p>Mi egy Cypern-i sz&eacute;khelyű c&eacute;g vagyunk. K&ouml;zponti irod&aacute;nk c&iacute;me:<br />\r\nTicketVilla Kft<br />\r\nDryadon, 1,<br />\r\n1. emelet,<br />\r\n6041, Larnaca, Ciprus.</p>', 'active', '2024-06-15 03:53:26', '2024-06-15 03:53:26'),
(9, 'What is a house raffle?', 'Was ist eine Häuserverlosung?', 'Mi az a házi tombola?', '<p>A house raffle is a unique opportunity for individuals to win a house or property through a &bdquo;lottery-style&rdquo; competition. Participants purchase eBooks and get a free tickets, and a winner is randomly selected from those entries.</p>', '<p>Eine Hausverlosung ist eine einmalige Gelegenheit f&uuml;r Einzelpersonen, bei einem Gewinnspiel im &bdquo;Lotterie-Stil&ldquo; ein Haus oder eine Immobilie zu gewinnen. Die Teilnehmer kaufen E-Books und erhalten kostenlose Lose. Aus diesen Einsendungen wird per Zufallsprinzip ein Gewinner ausgew&auml;hlt.</p>', '<p>A h&aacute;zi sorsol&aacute;s egyed&uuml;l&aacute;ll&oacute; lehetős&eacute;g mag&aacute;nszem&eacute;lyek sz&aacute;m&aacute;ra, hogy egy &bdquo;lott&oacute; jellegű&rdquo; versenyen kereszt&uuml;l h&aacute;zat vagy ingatlant nyerjenek. A r&eacute;sztvevők e-k&ouml;nyveket v&aacute;s&aacute;rolnak, &eacute;s ingyenes jegyeket kapnak, a nyertes pedig v&eacute;letlenszerűen ker&uuml;l kiv&aacute;laszt&aacute;sra a p&aacute;lyaművek k&ouml;z&uuml;l.</p>', 'active', '2024-06-15 03:54:29', '2024-06-15 03:54:29'),
(10, 'How does the house raffle work?', 'Wie funktioniert die Häuserverlosung?', 'Hogyan működik a házi sorsolás?', '<p>Participants purchasea eBook for a chance to win the featured house or property. Once the free ticket period ends, a random drawing selects the winning ticket number. The winner is then announced and awarded the house.</p>', '<p>Teilnehmer kaufen ein eBook und haben die Chance, das vorgestellte Haus oder Grundst&uuml;ck zu gewinnen. Nach Ablauf der Gratisticket-Periode wird die Gewinner-Losnummer per Zufallsprinzip ausgew&auml;hlt. Anschlie&szlig;end wird der Gewinner bekannt gegeben und erh&auml;lt das Haus.</p>', '<p>A r&eacute;sztvevők e-k&ouml;nyvet v&aacute;s&aacute;rolnak, hogy megnyerj&eacute;k a kiemelt h&aacute;zat vagy ingatlant. Az ingyenes jegy időszak&aacute;nak lej&aacute;rta ut&aacute;n v&eacute;letlenszerű sorsol&aacute;s v&aacute;lasztja ki a nyertes jegy sz&aacute;m&aacute;t. Ezut&aacute;n kihirdetik a győztest, &eacute;s oda&iacute;t&eacute;lik a h&aacute;zat.</p>', 'active', '2024-06-15 03:55:24', '2024-06-15 03:55:24');

