  `video_url_de` varchar(255) DEFAULT NULL,
  `video_url_hu` varchar(255) DEFAULT NULL,
  `icon` varchar(255) DEFAULT NULL,
  `icon_top_text_en` varchar(255) DEFAULT NULL,
  `icon_top_text_de` varchar(255) DEFAULT NULL,
  `icon_top_text_hu` varchar(255) DEFAULT NULL,
  `icon_bottom_text_en` varchar(255) DEFAULT NULL,
  `icon_bottom_text_de` varchar(255) DEFAULT NULL,
  `icon_bottom_text_hu` varchar(255) DEFAULT NULL,
  `sort_id` varchar(255) NOT NULL DEFAULT '0',
  `button_type` enum('buy_now','learn_more','both','none') NOT NULL DEFAULT 'buy_now',
